  app.post("/api/workers/quote-approvals/leads/:id/approve", isAuthenticated, requireEmployee, async (req: any, res) => {
    try {
      const user = req.currentUser;
      const canApprove = await userCanApproveQuotes(user);
      if (!canApprove) return res.status(403).json({ message: "Gold or Platinum authority required" });
      const notes = typeof req.body?.notes === "string" ? req.body.notes.slice(0, 1000) : null;
      const [lead] = await db.select().from(leads).where(eq(leads.id, req.params.id)).limit(1);
      if (!lead) return res.status(404).json({ message: "Lead not found" });

      const authority = await getWorkerAuthority(user);
      const isOwner = user.role === "business_owner" || user.email === "upmichiganstatemovers@gmail.com";
      let revision = await getLatestQuoteRevision(lead.id);
      if (!revision || revision.status !== "draft") {
        revision = await saveQuoteDraft({ leadId: lead.id, actorUserId: user.id, notes });
      }
      const approvedRevision = await approveQuoteRevision({
        quoteId: revision.id,
        actor: {
          userId: user.id,
          email: user.email,
          isOwner,
          canApproveStandard: authority.rank >= tierRank.gold,
        },
        overrideReason: notes,
      });
      await db.update(leads)
        .set({ status: "quote_requested" as any, lastQuoteUpdatedAt: new Date() })
        .where(eq(leads.id, lead.id));
      try {
        await writeLeadHistory(lead.id, lead.status, "quote_requested", user.id, "Quote revision approved by worker authority");
      } catch (histErr) {
        console.error("[lead_history] worker quote approval history failed:", histErr);
      }

      await db.insert(quoteAttributions).values({
        leadId: lead.id,
        userId: user.id,
        attributionType: "quote_approver",
        metadata: { quoteRevisionId: approvedRevision.id, notes },
      });

      try {
        if (authority.rank >= tierRank.gold) {
          const evidence = await evaluateOpsTaskCompletion("quote_approve", lead);
          if (evidence.ok) {
            await awardOpsTaskBonus({
              user,
              authorityTier: authority.authorityTier,
              taskKey: "quote_approve",
              lead,
              notes: notes || "Quote approved from worker approval flow.",
              metadata: { approved: true, quoteRevisionId: approvedRevision.id, ...evidence.metadata },
            });
          }
        }
      } catch (bonusError) {
        console.error("quote approval authority task bonus failed:", bonusError);
      }

      res.json({ success: true, approved: true, quote: approvedRevision });
    } catch (error) {
      console.error("worker quote approval error:", error);
      res.status(/owner|required|cannot|exceeds/i.test(error instanceof Error ? error.message : "") ? 403 : 500).json({ message: error instanceof Error ? error.message : "Failed to approve quote" });
    }
  });

  app.post("/api/jobs/:id/accept", isAuthenticated, requireEmployee, async (req: any, res) => {
    try {
      const leadId = req.params.id;
      const userId = req.currentUser.id;
      const [lead] = await db.select().from(leads).where(eq(leads.id, leadId));
      if (!lead) return res.status(404).json({ error: "Job not found" });
      const crew: string[] = Array.isArray(lead.crewMembers) ? lead.crewMembers : [];
      if (!crew.includes(userId)) return res.status(403).json({ error: "Not assigned to this job" });

      // Persist acceptance: add to acceptedByEmployees array (idempotent)
      const alreadyAccepted: string[] = Array.isArray(lead.acceptedByEmployees) ? lead.acceptedByEmployees : [];
      if (!alreadyAccepted.includes(userId)) {
        const [updatedLead] = await db.update(leads)
          .set({ acceptedByEmployees: [...alreadyAccepted, userId] })
          .where(eq(leads.id, leadId))
          .returning();
        if (updatedLead) {
          await emitJobEvent("job_updated", updatedLead, {
            actorId: userId,
            source: "assigned_job_accept",
            note: "Assigned crew member accepted the job.",
            extra: { acceptedByUserId: userId },
          });
        }
      }

      // Lock worker — mark unavailable so they won't be dispatched to new jobs
      await db.update(users).set({ isAvailable: false }).where(eq(users.id, userId));

      // Mark notification read
      await db.update(notifications)
        .set({ read: true })
        .where(and(eq(notifications.userId, userId), sql`data->>'leadId' = ${leadId}`));

      res.json({ success: true, message: "Job accepted" });
    } catch (err) {
      console.error("Error accepting job:", err);
      res.status(500).json({ error: "Failed to accept job" });
    }
  });

  // POST /api/jobs/:id/decline — crew member declines; re-dispatch replaces them
  app.post("/api/jobs/:id/decline", isAuthenticated, requireEmployee, async (req: any, res) => {
    try {
      const leadId = req.params.id;
      const userId = req.currentUser.id;
      const [lead] = await db.select().from(leads).where(eq(leads.id, leadId));
      if (!lead) return res.status(404).json({ error: "Job not found" });
      const crew: string[] = Array.isArray(lead.crewMembers) ? lead.crewMembers : [];
      if (!crew.includes(userId)) return res.status(403).json({ error: "Not assigned to this job" });

      // Confirmed slots stay; decliner is removed from crewMembers
      const confirmedCrew: string[] = (Array.isArray(lead.acceptedByEmployees) ? lead.acceptedByEmployees : [])
        .filter(id => id !== userId);
      const remainingCrew = crew.filter(id => id !== userId);

      await db.update(leads)
        .set({
          crewMembers: remainingCrew,
          acceptedByEmployees: confirmedCrew,
          status: "open",
        })
        .where(eq(leads.id, leadId));

      // Restore availability — worker declined so they're free for other jobs again
      await db.update(users).set({ isAvailable: true }).where(eq(users.id, userId));

      // Mark notification read
      await db.update(notifications)
        .set({ read: true })
        .where(and(eq(notifications.userId, userId), sql`data->>'leadId' = ${leadId}`));

      // Re-dispatch: preserve ALL remaining workers (confirmed + pending), find a replacement
      // Use crewSize >= 2 as a proxy for needsDriver (all multi-person tiers require a driver)
      const crewSize = lead.crewSize || 1;
      const slotsNeeded = crewSize - remainingCrew.length;
      if (slotsNeeded > 0) {
        await runDispatch(
          leadId,
          crewSize,
          slotsNeeded,
          crewSize >= 2, // needsDriver heuristic
          remainingCrew, // existingCrew — keep ALL currently assigned workers, not just confirmed
          [userId],      // excludeIds — skip the decliner
        );
      }

      res.json({ success: true, message: "Job declined" });
    } catch (err) {
      console.error("Error declining job:", err);
      res.status(500).json({ error: "Failed to decline job" });
    }
  });

  // GET /api/jobs/my-pending — jobs assigned to the employee that they haven't yet accepted
