  // Get single lead by ID — business owners/admins see all; crew members see only their assigned jobs
  app.get("/api/leads/:id", isAuthenticated, async (req: any, res) => {
    try {
      const { id } = req.params;

      // Resolve user from JWT (req.user), role middleware (req.currentUser), or session fallback
      let user = req.user || req.currentUser || null;
      if (!user) {
        const sessionUserId = (req.session as any)?.userId;
        if (sessionUserId) user = await storage.getUser(sessionUserId);
      }

      if (!user) return res.status(401).json({ error: "Not authenticated" });

      const lead = await storage.getLead(id);
      if (!lead) return res.status(404).json({ error: "Lead not found" });

      const isOwner = user.role === "admin" || user.role === "business_owner" || user.email === "upmichiganstatemovers@gmail.com";
      const isAssignedCrew =
        (user.role === "employee" || user.role === "admin" || user.role === "business_owner") &&
        (
          (Array.isArray(lead.crewMembers) && lead.crewMembers.includes(user.id)) ||
          lead.assignedToUserId === user.id
        );

      if (!isOwner && !isAssignedCrew) {
        return res.status(403).json({ error: "Access denied" });
      }

      const authorityTier = isOwner ? "platinum" : (await getWorkerAuthority(user)).authorityTier;
      res.json(await presentJobFlowRecordWithEarnings(lead, user, isOwner || isAssignedCrew, authorityTier, isOwner ? "admin" : undefined));
    } catch (error) {
      console.error("Error fetching lead:", error);
      res.status(500).json({ error: "Failed to fetch lead" });
    }
  });

  // Allowed forward transitions (enforced pipeline)
  // new/quote_requested → quoted → available (confirmed is an alias for available) → in_progress → completed
  // accepted (crew-full from job accept flow) → in_progress is also a valid path
  const LEAD_TRANSITIONS: Record<string, string> = {
    "new":            "quoted",
    "quote_requested":"quoted",
    "quoted":         "available",
    "confirmed":      "in_progress",  // legacy alias: confirmed = available
    "available":      "in_progress",
    "assigned":       "in_progress",  // admin-pinned crew can begin work
    "accepted":       "in_progress",  // crew-full accepted jobs progress to in_progress
    "dispatched":     "in_progress",  // paid + dispatched jobs can start from the lead page
    "in_progress":    "completed",
    "completed":      "customer_approved",
    "customer_approved": "payout_calculated",
    "payout_calculated": "payout_sent",
    "payout_sent":    "closed",
  };

  // Helper: write a lead_history row
  async function writeLeadHistory(leadId: string, fromStatus: string | null, toStatus: string, changedByUserId: string | null, note?: string) {
    await pool.query(
      `INSERT INTO lead_history (lead_id, from_status, to_status, changed_by_user_id, note) VALUES ($1,$2,$3,$4,$5)`,
      [leadId, fromStatus ?? null, toStatus, changedByUserId ?? null, note ?? null]
    );
  }

  const cleanMoneyValue = (value: unknown) => {
    if (typeof value === "number") return Number.isFinite(value) ? value : undefined;
    const text = String(value ?? "").replace(/,/g, "").trim();
    if (!text) return undefined;
    const matches = text.match(/\d+(?:\.\d{1,2})?/g);
    if (!matches?.length) return undefined;
    const values = matches.map(Number).filter(Number.isFinite);
    if (!values.length) return undefined;
    if (values.length >= 2 && /(?:-|\u2013|\u2014|\bto\b)/i.test(text)) {
      return Math.round(((values[0] + values[1]) / 2) * 100) / 100;
    }
    return Math.round(values[0] * 100) / 100;
  };

  const moneyField = (message: string) => z.preprocess(cleanMoneyValue, z.number().positive(message));
  const convertLineItemSchema = z.object({
    id: z.string().trim().min(1).max(120),
    name: z.string().trim().min(1).max(160),
    qty: z.coerce.number().positive().max(999).default(1),
    unitPrice: moneyField("Line item price is required"),
    total: moneyField("Line item total is required"),
    category: z.string().trim().max(80).optional(),
  }).passthrough();

  const convertLeadToJobSchema = z.object({
    basePrice: moneyField("Base price is required"),
    totalPrice: moneyField("Total price is required").optional(),
    tokenAllocation: z.coerce.number().min(0).optional(),
    confirmedDate: z.string().trim().min(1, "Confirmed date is required"),
    arrivalWindow: z.string().trim().max(80).optional(),
    crewSize: z.coerce.number().int().min(1).max(12).default(2),
    confirmedHours: z.coerce.number().positive().max(24).optional(),
    crewMembers: z.array(z.string()).default([]),
    confirmedFromAddress: z.string().trim().max(500).optional(),
    confirmedToAddress: z.string().trim().max(500).optional(),
    quoteNotes: z.string().trim().max(2000).optional(),
    dispatchNotes: z.string().trim().max(2000).optional(),
    selectedPackageId: z.string().trim().max(120).optional(),
    orderLineItems: z.array(convertLineItemSchema).max(24).optional(),
    quoteSnapshot: z.record(z.any()).optional(),
    sourceAction: z.string().trim().max(80).optional(),
  });

  app.post("/api/leads/:id/convert-to-job", isAuthenticated, requireEmployee, async (req: any, res) => {
    try {
      const { id } = req.params;
      const user = req.currentUser;
      const authority = await getWorkerAuthority(user);
      const canConvert = user?.role === "admin"
        || user?.role === "business_owner"
        || user?.email === "upmichiganstatemovers@gmail.com"
        || authority.rank >= tierRank.silver;

      if (!canConvert) {
        return res.status(403).json({ error: "Silver worker authority or owner/admin access is required to convert leads to jobs." });
      }

      const parsed = convertLeadToJobSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid conversion details", details: parsed.error.flatten() });
      }

      const existingLead = await storage.getLead(id);
      if (!existingLead) return res.status(404).json({ error: "Lead not found" });

      const convertibleStatuses = new Set(["new", "quote_requested", "contacted", "quoted", "chatbot_pending"]);
      // The Ops Board also opens this editor for jobs that are already
      // scheduled or dispatched. A later save must preserve that lifecycle
      // status rather than trying to convert the job back to "available".
      const editableJobStatuses = new Set(["available", "assigned", "accepted", "dispatched", "in_progress"]);
      const isExistingJob = editableJobStatuses.has(existingLead.status);
      if (!convertibleStatuses.has(existingLead.status) && !isExistingJob) {
        return res.status(400).json({
          error: `Job status '${existingLead.status}' is no longer editable from the quote board. Open the full job record to continue its lifecycle.`,
        });
      }

      const data = parsed.data;
      const money = (value: number) => value.toFixed(2);
      const basePrice = Math.round(data.basePrice * 100) / 100;
      const totalPrice = Math.round((data.totalPrice ?? data.basePrice) * 100) / 100;
      const confirmedHours = data.confirmedHours != null
        ? Math.max(1, Math.ceil(data.confirmedHours))
        : existingLead.confirmedHours ?? null;
      const sanitizedLineItems = (data.orderLineItems || []).map((item) => ({
        ...item,
        qty: Math.round(Number(item.qty) * 100) / 100,
        unitPrice: Math.round(Number(item.unitPrice) * 100) / 100,
        total: Math.round(Number(item.total) * 100) / 100,
      }));
      const currentSnapshot = existingLead.quoteSnapshot && typeof existingLead.quoteSnapshot === "object" && !Array.isArray(existingLead.quoteSnapshot)
        ? existingLead.quoteSnapshot as Record<string, unknown>
        : {};
      const sourceAction = data.sourceAction || "lead_convert_to_job";
      const crewMembers = Array.from(new Set(
        (data.crewMembers || [])
          .map((memberId) => String(memberId || "").trim())
          .filter(Boolean),
      ));
      const primaryAssignee = existingLead.assignedToUserId && crewMembers.includes(existingLead.assignedToUserId)
        ? existingLead.assignedToUserId
        : crewMembers[0] || null;
      const nextStatus = isExistingJob ? existingLead.status : "available";
      const updateData: Record<string, any> = {
        status: nextStatus,
        basePrice: money(basePrice),
        totalPrice: money(totalPrice),
        confirmedDate: data.confirmedDate,
        arrivalWindow: data.arrivalWindow || null,
        crewSize: data.crewSize,
        confirmedHours,
        crewMembers,
        assignedToUserId: primaryAssignee,
        confirmedFromAddress: data.confirmedFromAddress || existingLead.fromAddress,
        confirmedToAddress: data.confirmedToAddress || existingLead.toAddress || null,
        lastQuoteUpdatedAt: new Date(),
      };

      if (data.tokenAllocation !== undefined) {
        updateData.tokenAllocation = String(data.tokenAllocation);
      }
      if (data.selectedPackageId) {
        updateData.selectedPackageId = data.selectedPackageId;
      }
      if (sanitizedLineItems.length > 0) {
        updateData.orderLineItems = sanitizedLineItems;
      }
      if (data.quoteNotes) {
        updateData.quoteNotes = data.quoteNotes;
      }
      if (data.dispatchNotes !== undefined) {
        updateData.dispatchNotes = data.dispatchNotes || null;
      }
      if (data.quoteSnapshot || data.selectedPackageId || sanitizedLineItems.length > 0 || data.dispatchNotes) {
        updateData.quoteSnapshot = {
          ...currentSnapshot,
          ...(data.quoteSnapshot || {}),
          adminSmallJobIntake: {
            ...((data.quoteSnapshot as any)?.adminSmallJobIntake || {}),
            source: sourceAction,
            selectedPackageId: data.selectedPackageId || null,
            basePrice: money(basePrice),
            totalPrice: money(totalPrice),
            crewSize: data.crewSize,
            confirmedHours,
            arrivalWindow: data.arrivalWindow || null,
            dispatchNotes: data.dispatchNotes || null,
            lineItemCount: sanitizedLineItems.length,
            convertedAt: new Date().toISOString(),
            convertedByUserId: user?.id ?? null,
          },
        };
      }

      const [updatedLead] = await db.update(leads).set(updateData).where(eq(leads.id, id)).returning();
      if (!updatedLead) return res.status(404).json({ error: "Lead not found" });

      await writeLeadHistory(
        id,
        existingLead.status,
        nextStatus,
        user?.id ?? null,
        isExistingJob
          ? "Updated quote, schedule, or crew details without changing job lifecycle status"
          : sourceAction === "text_lead_fast_path"
            ? "Text-message lead booked from small-job admin intake"
            : "Converted to available job from employee dashboard",
      );

      if (!isExistingJob) {
        try {
          const employees = await storage.getEmployees();
          const customerName = `${updatedLead.firstName || ""} ${updatedLead.lastName || ""}`.trim() || "Customer";
          const jobData = {
            customerName,
            serviceType: updatedLead.serviceType || "service",
            moveDate: updatedLead.confirmedDate || updatedLead.moveDate || undefined,
            tokensReward: updatedLead.tokenAllocation ? Number(updatedLead.tokenAllocation) : undefined,
          };
          await Promise.allSettled(
            employees.flatMap((employee) => {
              const sends: Promise<unknown>[] = [];
              if (employee.email) {
                sends.push(notifyEmployeeJobAvailable(employee.email, jobData));
              }
              if ((employee as any).phoneNumber) {
                sends.push(smsService.notifyJobAvailable((employee as any).phoneNumber, jobData));
              }
              return sends;
            }),
          );
        } catch (notifyError) {
          console.error("Failed to notify employees after lead conversion:", notifyError);
        }
      }

      await emitJobEvent(isExistingJob ? "job_updated" : "job_available", updatedLead, {
        actorId: user?.id ?? null,
        source: sourceAction,
        previousStatus: existingLead.status,
        status: nextStatus,
        note: isExistingJob
          ? "Quote, schedule, or crew details were updated while preserving the job lifecycle."
          : sourceAction === "text_lead_fast_path"
            ? "Text-message lead booked from small-job admin intake."
            : "Converted to available job from employee dashboard.",
      });

      try {
        if (!isExistingJob && authority.rank >= tierRank.silver) {
          const evidence = await evaluateOpsTaskCompletion("quote_build", updatedLead);
          if (evidence.ok) {
            await awardOpsTaskBonus({
              user,
              authorityTier: authority.authorityTier,
              taskKey: "quote_build",
              lead: updatedLead,
              notes: "Converted request into an available priced job.",
              metadata: { sourceAction: "convert_to_job", ...evidence.metadata },
            });
          }
        }
      } catch (bonusError) {
        console.error("quote build authority task bonus failed:", bonusError);
      }

      res.json({ ...updatedLead, lifecycleAction: isExistingJob ? "updated" : "created" });
    } catch (error) {
      console.error("Error converting lead to job:", error);
      res.status(500).json({ error: "Failed to convert lead to job" });
    }
  });

  // GET lead history
  app.get("/api/leads/:id/history", isAuthenticated, requireBusinessOwner, async (req, res) => {
    try {
      const { id } = req.params;
      const { rows } = await pool.query(`
        SELECT lh.id, lh.lead_id, lh.from_status, lh.to_status, lh.note, lh.created_at,
               u.first_name, u.last_name
        FROM lead_history lh
        LEFT JOIN users u ON u.id = lh.changed_by_user_id
        WHERE lh.lead_id = $1
        ORDER BY lh.created_at ASC
      `, [id]);
      res.json(rows);
    } catch (error) {
      console.error("Error fetching lead history:", error);
      res.status(500).json({ error: "Failed to fetch lead history" });
    }
  });

  // Force-override status (admin only — skips transition check)
  app.patch("/api/leads/:id/status/force", isAuthenticated, requireAdmin, async (req: any, res) => {
    try {
      const { id } = req.params;
      const { status, note } = req.body;
      const actorId = (req.session as any)?.userId ?? req.user?.id ?? null;

      const VALID_LEAD_STATUSES = ["new", "contacted", "quoted", "confirmed", "available", "accepted", "dispatched", "in_progress", "completed", "customer_approved", "payout_calculated", "payout_sent", "closed", "cancelled", "quote_requested"];
      if (!status || !VALID_LEAD_STATUSES.includes(status)) {
        return res.status(400).json({ error: `Invalid status. Must be one of: ${VALID_LEAD_STATUSES.join(", ")}` });
      }

      const existingLead = await storage.getLead(id);
      if (!existingLead) return res.status(404).json({ error: "Lead not found" });

      let updatedLead = await storage.updateLeadStatus(id, status);
      if (!updatedLead) return res.status(404).json({ error: "Lead not found" });

      const now = new Date();
      const dispatchPatch: Record<string, any> = {};
      if (status === "completed") {
        dispatchPatch.dispatchState = "completed";
        dispatchPatch.enRouteAt = existingLead.enRouteAt || now;
        dispatchPatch.onSiteAt = existingLead.onSiteAt || now;
        dispatchPatch.completedAt = existingLead.completedAt || now;
      } else if (status === "in_progress") {
        dispatchPatch.dispatchState = existingLead.dispatchState === "on_site" ? "on_site" : "en_route";
        dispatchPatch.enRouteAt = existingLead.enRouteAt || now;
      } else if (status === "accepted" || status === "dispatched") {
        dispatchPatch.dispatchState = "assigned";
        dispatchPatch.dispatchOfferedTo = null;
        dispatchPatch.dispatchOfferExpiresAt = null;
      } else if (status === "available" || status === "confirmed" || status === "quoted" || status === "quote_requested" || status === "new") {
        dispatchPatch.dispatchState = "pending";
        dispatchPatch.dispatchOfferedTo = null;
        dispatchPatch.dispatchOfferExpiresAt = null;
      } else if (status === "cancelled") {
        dispatchPatch.dispatchState = "failed";
        dispatchPatch.dispatchOfferedTo = null;
        dispatchPatch.dispatchOfferExpiresAt = null;
      }

      if (Object.keys(dispatchPatch).length > 0) {
        updatedLead = await storage.updateLeadQuote(id, dispatchPatch) || updatedLead;
      }

      await writeLeadHistory(id, existingLead.status, status, actorId, note || "Admin force override");
      const eventType = eventTypeForStatus(status);
      if (eventType) {
        await emitJobEvent(eventType, updatedLead, {
          actorId,
          source: "lead_status_force",
          previousStatus: existingLead.status,
          status,
          note: note || "Admin force override",
        });
      }

      if (status === "completed" && existingLead.status !== "completed") {
        try {
          const { runCompletionStep } = await import('./pipeline/steps/completion.step');
          await runCompletionStep(id);
        } catch (completionError) {
          console.error("Admin force completion pipeline failed:", completionError);
        }
      }

      res.json(updatedLead);
    } catch (error) {
      console.error("Error force-updating lead status:", error);
      res.status(500).json({ error: "Failed to force update lead status" });
    }
  });

  // Protected routes - Update lead status through the enforced pipeline.
  // Owner/admin can advance any normal step. Worker authority rails can advance
  // quote/job stages without needing the separate business_owner role.
  app.patch("/api/leads/:id/status", isAuthenticated, requireEmployee, async (req: any, res) => {
    try {
      const { id } = req.params;
      const { status } = req.body;
      const actorId = (req.session as any)?.userId ?? req.user?.id ?? null;

      const VALID_LEAD_STATUSES = ["new", "contacted", "quoted", "confirmed", "available", "accepted", "dispatched", "in_progress", "completed", "customer_approved", "payout_calculated", "payout_sent", "closed", "cancelled", "quote_requested"];
      if (!status || !VALID_LEAD_STATUSES.includes(status)) {
        return res.status(400).json({ error: `Invalid status. Must be one of: ${VALID_LEAD_STATUSES.join(", ")}` });
      }

      // Enforce pipeline transitions
      const existingLead = await storage.getLead(id);
      if (!existingLead) return res.status(404).json({ error: "Lead not found" });

      const currentStatus = existingLead.status;

      // If the current status is in the transition map, only allow the exact next step
      // If it is NOT in the map (e.g. completed, cancelled, contacted, accepted) it is
      // a terminal or legacy status — all forward/backward changes require the force endpoint
      if (currentStatus in LEAD_TRANSITIONS) {
        const allowedNext = LEAD_TRANSITIONS[currentStatus];
        if (status !== allowedNext) {
          return res.status(400).json({
            error: `Invalid transition: ${currentStatus} → ${status}. Expected next stage: ${allowedNext}. Use the force endpoint to override.`
          });
        }
      } else {
        // Status not in the transition map: terminal or legacy — require force
        return res.status(400).json({
          error: `Cannot change status from '${currentStatus}' via this endpoint. Use the force endpoint to correct pipeline stage.`
        });
      }

      const user = req.currentUser || req.user || null;
      const isOwner = user?.role === "admin" || user?.role === "business_owner" || user?.email === "upmichiganstatemovers@gmail.com";
      const authority = user ? await getWorkerAuthority(user) : { rank: 0 };
      const isQuoteStage =
        (["new", "quote_requested", "chatbot_pending", "contacted"].includes(currentStatus) && status === "quoted") ||
        (currentStatus === "quoted" && status === "available");
      const canUseWorkerRail =
        authority.rank >= tierRank.platinum ||
        (isQuoteStage && authority.rank >= tierRank.silver);

      if (!isOwner && !canUseWorkerRail) {
        return res.status(403).json({
          error: "Worker authority required",
          message: isQuoteStage
            ? "Silver or higher worker authority is required to quote or confirm jobs."
            : "Platinum worker authority is required to manage this pipeline transition.",
        });
      }

      const updatedLead = await storage.updateLeadStatus(id, status);
      if (!updatedLead) {
        return res.status(404).json({ error: "Lead not found" });
      }

      // Log the history
      await writeLeadHistory(id, currentStatus, status, actorId);
      const eventType = eventTypeForStatus(status);
      if (eventType) {
        await emitJobEvent(eventType, updatedLead, {
          actorId,
          source: "lead_status",
          previousStatus: currentStatus,
          status,
        });
      }

      // Send email notifications for status changes
      try {
        // Notify when job becomes available
        if (status === 'available') {
          // Send email to all employees with email addresses
          try {
            const allUsers = await storage.getAllUsers();
            const employees = allUsers.filter(u => u.role === 'employee' && (u.status === 'active' || u.status === 'approved') && u.email);
            for (const emp of employees) {
              if (emp.email) {
                await notifyEmployeeJobAvailable(emp.email, {
                  customerName: `${updatedLead.firstName} ${updatedLead.lastName}`,
                  serviceType: updatedLead.serviceType,
                  moveDate: updatedLead.confirmedDate || updatedLead.moveDate || undefined,
                  tokensReward: updatedLead.tokenAllocation ? parseFloat(updatedLead.tokenAllocation) : undefined
                });
              }
            }
          } catch (e) { console.error('Email to employees failed:', e); }
          
          // Send email to customer confirming job availability
          if (updatedLead.email) {
            try {
              await sendNotificationEmail(
                updatedLead.email,
                `Your JC ON THE MOVE ${updatedLead.serviceType} Job is Confirmed`,
                `<h2>Great news, ${updatedLead.firstName}!</h2><p>Your <strong>${updatedLead.serviceType}</strong> job has been confirmed and is now available for scheduling. We'll be in touch soon!</p><p>Questions? Call us anytime at (906) 285-9312.</p>`
              );
            } catch (e) { console.error('Customer email failed:', e); }
          }
        }
        
        // Notify when job is completed
        if (status === 'completed') {
          // Disburse JCMOVES tokens idempotently on every completion path
          try {
            const { disburseJobTokens } = await import('./services/disburse-job-tokens');
            await disburseJobTokens(id);
          } catch (disbursementError) {
            console.error("Error distributing job completion tokens via status endpoint:", disbursementError);
            // Don't fail the status update if token distribution fails
          }

          // Grant 3 lottery tickets to the customer on job completion
          try {
            if (updatedLead.email) {
              const { rows: customerRows } = await pool.query(
                `SELECT id FROM users WHERE LOWER(email) = LOWER($1) LIMIT 1`,
                [updatedLead.email.trim()]
              );
              if (customerRows.length > 0) {
                await grantLotteryTicketsForActivity(customerRows[0].id, 3, 'completion');
              }
            }
          } catch (lotteryErr) {
            console.error("Lottery ticket grant on completion failed (non-fatal):", lotteryErr);
          }

          // Send email to admin
          try {
            const assignedUser = updatedLead.assignedToUserId 
              ? await storage.getUser(updatedLead.assignedToUserId)
              : null;
            await notifyAdminJobCompleted({
              customerName: `${updatedLead.firstName} ${updatedLead.lastName}`,
              serviceType: updatedLead.serviceType,
              completedBy: assignedUser ? `${assignedUser.firstName} ${assignedUser.lastName}` : undefined
            });
          } catch (e) { console.error('Admin email failed:', e); }
          
          // Send email to customer thanking them
          if (updatedLead.email) {
            try {
              await sendNotificationEmail(
                updatedLead.email,
                `Thank You — Your JC ON THE MOVE Job is Complete!`,
                `<h2>Thank you for choosing us, ${updatedLead.firstName}!</h2><p>Your <strong>${updatedLead.serviceType}</strong> job has been completed. We'd love your feedback — please leave us a review!</p><p>Questions? Call anytime at (906) 285-9312!</p>`
              );
            } catch (e) { console.error('Customer email failed:', e); }
          }

          // Bundle follow-up email: 10% promo code — only for single-service (non-bundle) bookings
          // Send exactly one tokenized review link and record it on the job.
          // A mail failure does not undo completion, rewards, or dispatch data.
          try {
            await sendCompletedJobReviewRequest(updatedLead);
          } catch (reviewError) {
            console.error("Automatic review request failed (non-fatal):", reviewError);
          }

          if (updatedLead.email && !updatedLead.bundleFollowupSentAt && !updatedLead.selectedPackageId) {
            try {
              const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days
              // Look up customer userId by email (case-insensitive)
              const emailNorm = updatedLead.email.trim().toLowerCase();
              const [customerRow] = await db
                .select({ id: users.id })
                .from(users)
                .where(sql`lower(${users.email}) = ${emailNorm}`)
                .limit(1);
              const custUserId = customerRow?.id ?? null;
              const promoCode = await generateBundleFollowupCode(custUserId, 10, expiresAt);
              await sendBundleFollowupEmail({
                to: updatedLead.email,
                firstName: updatedLead.firstName || "there",
                promoCode,
                discountPct: 10,
                expiresAt,
              });
              // Mark sent
              await db.update(leads)
                .set({ bundleFollowupSentAt: new Date() })
                .where(eq(leads.id, updatedLead.id));
              console.log(`✅ Bundle follow-up 10% email sent to ${updatedLead.email} — code ${promoCode}`);
            } catch (bundleErr) {
              console.error("Bundle follow-up email failed (non-fatal):", bundleErr);
            }
          }
        }
        
      } catch (notificationError) {
        console.error("Error sending status change notification:", notificationError);
        // Don't fail the request if notification fails
      }

      res.json(updatedLead);
    } catch (error) {
      console.error("Error updating lead status:", error);
      if (error instanceof Error && error.message.includes("Cannot set status to 'accepted'")) {
        return res.status(400).json({ error: error.message });
      }
      res.status(500).json({ error: "Failed to update lead status" });
    }
  });

  // Owner fallback for jobs that were scheduled before today but whose crew
  // never tapped the field-status buttons. The date guard prevents an active
  // job from being completed early, while still letting ops close real work
  // and trigger its normal JCMOVES/review trail.
  app.post("/api/leads/:id/complete-overdue", isAuthenticated, requireBusinessOwner, async (req: any, res) => {
    try {
      const lead = await storage.getLead(req.params.id);
      if (!lead) return res.status(404).json({ error: "Lead not found" });
      if (lead.status === "completed") return res.json({ lead, alreadyCompleted: true });

      const scheduledDate = String(lead.confirmedDate || lead.moveDate || "").trim().slice(0, 10);
      const today = getEasternDateStr();
      if (!/^\d{4}-\d{2}-\d{2}$/.test(scheduledDate) || scheduledDate >= today) {
        return res.status(409).json({
          error: "Only jobs with a confirmed move date before today can be marked complete from the overdue-job action.",
        });
      }

      const completableStatuses = new Set(["available", "assigned", "accepted", "dispatched", "in_progress"]);
      if (!completableStatuses.has(String(lead.status || "").toLowerCase())) {
        return res.status(409).json({ error: `Job status '${lead.status}' cannot be completed from the overdue-job action.` });
      }

      const now = new Date();
      const [completedLead] = await db.update(leads).set({
        status: "completed",
        dispatchState: "completed",
        enRouteAt: lead.enRouteAt || now,
        onSiteAt: lead.onSiteAt || now,
        completedAt: lead.completedAt || now,
      }).where(eq(leads.id, lead.id)).returning();
      if (!completedLead) return res.status(404).json({ error: "Lead not found" });

      const actorId = req.currentUser?.id || req.user?.id || null;
      await writeLeadHistory(lead.id, lead.status, "completed", actorId, "Marked complete after confirmed move date passed");

      const { runCompletionStep } = await import("./pipeline/steps/completion.step");
      const completion = await runCompletionStep(lead.id);
      let review: ReviewRequestResult | null = null;
      try {
        review = await sendCompletedJobReviewRequest(completedLead);
      } catch (reviewError) {
        console.error("Overdue completion review request failed (non-fatal):", reviewError);
      }
      await emitJobEvent("job_completed", completedLead, {
        actorId,
        source: "overdue_job_completion",
        previousStatus: lead.status,
        status: "completed",
        note: "Owner marked job complete after the confirmed move date passed.",
      });

      res.json({ lead: completedLead, completion, review });
    } catch (error: any) {
      console.error("Error completing overdue job:", error);
      res.status(error.status || 500).json({ error: error.message || "Failed to complete overdue job" });
    }
  });

  type ReviewRequestResult = {
    reviewLink: string;
    sent: boolean;
    alreadySent: boolean;
  };

  async function sendCompletedJobReviewRequest(lead: any): Promise<ReviewRequestResult> {
    if (lead.status !== "completed") {
      throw Object.assign(new Error("Can only request reviews for completed jobs"), { status: 400 });
    }
    if (!String(lead.email || "").trim()) {
      throw Object.assign(new Error("This completed job has no customer email for a review request"), { status: 400 });
    }

    const reviewToken = lead.reviewToken || crypto.randomBytes(24).toString("hex");
    const reviewLink = `${getAppUrl()}/leave-review?token=${encodeURIComponent(reviewToken)}`;
    if (lead.reviewRequestSentAt) {
      return { reviewLink, sent: false, alreadySent: true };
    }

    if (!lead.reviewToken) {
      await db.update(leads).set({ reviewToken }).where(eq(leads.id, lead.id));
    }

    const serviceLabels: Record<string, string> = {
      residential: "Moving",
      commercial: "Commercial Moving",
      junk: "Junk Removal",
      snow: "Snow Removal",
      cleaning: "Move In/Out Cleaning",
      handyman: "Handyman",
      demolition: "Light Demolition",
      flooring: "Flooring",
      painting: "Painting",
    };
    const serviceLabel = serviceLabels[lead.serviceType] || lead.serviceType || "service";
    const companyEmail = process.env.COMPANY_EMAIL || "michigankid906@gmail.com";
    const emailHtml = `
      <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
        <h2 style="color: #333;">How was your experience with JC ON THE MOVE?</h2>
        <p>Hi ${lead.firstName},</p>
        <p>Thank you for choosing JC ON THE MOVE for your ${serviceLabel} service! We hope everything went smoothly.</p>
        <p>We'd love to hear about your experience. Your feedback helps us improve and helps other customers find quality service.</p>
        <div style="text-align: center; margin: 30px 0;">
          <a href="${reviewLink}" style="background-color: #f59e0b; color: white; padding: 12px 24px; text-decoration: none; border-radius: 6px; font-weight: bold;">Leave a Review</a>
        </div>
        <p>Thank you for your business!</p>
        <p>- The JC ON THE MOVE Team</p>
      </div>
    `;
    const emailText = `Hi ${lead.firstName},

Thank you for choosing JC ON THE MOVE for your ${serviceLabel} service! We hope everything went smoothly.

We'd love to hear about your experience. Your feedback helps us improve and helps other customers find quality service.

Leave a review here: ${reviewLink}

Thank you for your business!
- The JC ON THE MOVE Team`;

    await sendEmail({
      to: lead.email,
      from: companyEmail,
      subject: `How was your ${serviceLabel} service with JC ON THE MOVE?`,
      text: emailText,
      html: emailHtml,
    });
    await db.update(leads).set({ reviewToken, reviewRequestSentAt: new Date() }).where(eq(leads.id, lead.id));
    console.log(`Review request sent to ${lead.email} for job ${lead.id}`);
    return { reviewLink, sent: true, alreadySent: false };
  }

  // Request a review from customer for completed job
  app.post("/api/leads/:id/request-review", isAuthenticated, async (req: any, res) => {
    try {
      const { id } = req.params;
      
      // Get the lead
      const lead = await storage.getLead(id);
      if (!lead) {
        return res.status(404).json({ error: "Lead not found" });
      }
      
      // Only completed jobs can receive review requests
      if (lead.status !== 'completed') {
        return res.status(400).json({ error: "Can only request reviews for completed jobs" });
      }

      const actor = req.currentUser || req.user || null;
      const isOwner = actor?.role === "admin"
        || actor?.role === "business_owner"
        || actor?.email === "upmichiganstatemovers@gmail.com";
      const crewIds = new Set([lead.assignedToUserId, ...(lead.crewMembers || [])].filter(Boolean));
      if (!isOwner && !crewIds.has(actor?.id)) {
        return res.status(403).json({ error: "Only the assigned crew or an owner can request this review." });
      }

      const result = await sendCompletedJobReviewRequest(lead);
      return res.json({
        success: true,
        message: result.alreadySent ? "Review request was already sent" : "Review request sent successfully",
        ...result,
      });
    } catch (error) {
      console.error("Error sending review request:", error);
      res.status(500).json({ error: "Failed to send review request" });
    }
  });

  // =====================
  // PUBLIC REVIEW / TIP ROUTES (no auth required — token based)
  // =====================

  type ReviewCrewMember = {
    id: string;
    name: string;
    firstName: string | null;
    lastName: string | null;
    profileImageUrl: string | null;
  };

  type TipMethod = "cash" | "cart" | "bitcoin" | "jcmoves" | "jcmoves_usd";

  type NormalizedTipAllocation = {
    workerId: string;
    workerName: string | null;
    amountUsd: number;
    tokenAmount: number;
  };

  class ReviewTipError extends Error {
    status: number;

    constructor(status: number, message: string) {
      super(message);
      this.status = status;
    }
  }

  async function getReviewCrewMembers(lead: any): Promise<ReviewCrewMember[]> {
    const employees: ReviewCrewMember[] = [];
    const seenIds = new Set<string>();
    for (const eid of getReviewCrewIds(lead)) {
      if (seenIds.has(eid)) continue;
      seenIds.add(eid);
      const emp = await storage.getUser(eid);
      if (!emp || emp.role === "customer") continue;
      const firstName = emp.firstName || "";
      const lastName = emp.lastName || "";
      const name = `${firstName} ${lastName}`.trim() || emp.username || emp.email || "Crew Member";
      employees.push({
        id: emp.id,
        name,
        firstName: firstName || null,
        lastName: lastName || null,
        profileImageUrl: emp.profileImageUrl || null,
      });
    }
    return employees;
  }

  async function getJobInfoByLead(lead: any) {
    const serviceLabels: Record<string, string> = {
      residential: "Residential Moving", commercial: "Commercial Moving",
      junk: "Junk Removal", snow: "Snow Removal", cleaning: "Move In/Out Cleaning",
      handyman: "Handyman", demolition: "Light Demolition", flooring: "Flooring", painting: "Painting",
    };
    const employees = await getReviewCrewMembers(lead);
    return {
      jobId: lead.id,
      customerName: `${lead.firstName}`,
      serviceType: lead.serviceType,
      serviceLabel: serviceLabels[lead.serviceType] || lead.serviceType,
      completedDate: lead.createdAt ? new Date(lead.createdAt).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }) : null,
      assignedEmployees: employees,
      crewSize: lead.crewSize || 2,
    };
  }

  function getReviewCrewIds(lead: any): string[] {
    const ids = [
      ...(Array.isArray(lead.crewMembers) ? lead.crewMembers : []),
      ...(Array.isArray(lead.acceptedByEmployees) ? lead.acceptedByEmployees : []),
      ...(lead.assignedToUserId ? [lead.assignedToUserId] : []),
    ].map((id) => String(id || "").trim()).filter(Boolean);
    return Array.from(new Set(ids)).filter((id) => id !== "staking-treasury-system");
  }

  async function getRewardSettingAmount(settingKey: string, fallback: number): Promise<number> {
    const [setting] = await db
      .select()
      .from(rewardSettings)
      .where(eq(rewardSettings.settingKey, settingKey))
      .limit(1);
    if (!setting) return fallback;
    if (!setting.isActive) return 0;
    const amount = Number(setting.tokenAmount);
    return Number.isFinite(amount) ? amount : fallback;
  }

  async function rewardLedgerExists(userId: string, rewardType: string, referenceId: string): Promise<boolean> {
    const existing = await db
      .select({ id: rewards.id })
      .from(rewards)
      .where(and(
        eq(rewards.userId, userId),
        eq(rewards.rewardType, rewardType),
        eq(rewards.referenceId, referenceId),
      ))
      .limit(1);
    return existing.length > 0;
  }

  async function resolveLeadCustomerUserId(lead: any, preferredUserId?: string | null): Promise<string | null> {
    if (preferredUserId) return preferredUserId;
    if (lead.userId) return String(lead.userId);
    const email = String(lead.email || "").trim();
    if (!email) return null;
    const user = await storage.getUserByEmail(email).catch(() => null);
    return user?.id || null;
  }

  async function awardCustomerReviewBonus(lead: any, review: any, preferredUserId?: string | null) {
    const customerUserId = await resolveLeadCustomerUserId(lead, preferredUserId);
    if (!customerUserId) return { awarded: false, userId: null, tokens: 0, reason: "customer_account_not_found" };

    const rewardType = "customer_review_submitted";
    const referenceId = review.id;
    if (await rewardLedgerExists(customerUserId, rewardType, referenceId)) {
      return { awarded: false, userId: customerUserId, tokens: 0, reason: "already_awarded" };
    }

    const tokens = await getRewardSettingAmount(rewardType, 250);
    if (tokens <= 0) return { awarded: false, userId: customerUserId, tokens: 0, reason: "disabled_or_zero" };

    await storage.creditWalletTokens(customerUserId, tokens, {
      rewardType,
      referenceId,
      metadata: {
        leadId: lead.id,
        reviewId: review.id,
        rating: review.rating,
        source: "completed_job_review",
      },
    });
    return { awarded: true, userId: customerUserId, tokens };
  }

  async function awardCrewReviewBonuses(lead: any, review: any) {
    if (Number(review.rating) < 4) return [];
    const awards = [];
    for (const crewId of getReviewCrewIds(lead)) {
      if (await rewardLedgerExists(crewId, "customer_rating_bonus", review.id)) {
        awards.push({ awarded: false, userId: crewId, tokens: 0, reason: "already_awarded" });
        continue;
      }
      const result = await gamificationService.awardHighRatingBonus(crewId, review.id, Number(review.rating));
      awards.push({
        awarded: result.success && Number(result.tokensAwarded) > 0,
        userId: crewId,
        tokens: Number(result.tokensAwarded || 0),
        points: result.points,
        error: result.error,
      });
    }
    if (awards.some((award) => award.awarded)) {
      await storage.markReviewAsRewarded(review.id);
    }
    return awards;
  }

  // POST: Customer self-service job lookup (public — no auth required)
  function getRequestUserId(req: any): string | null {
    return req?.user?.id || req?.session?.userId || null;
  }

  function normalizeTipMethod(value: unknown): TipMethod | null {
    if (typeof value !== "string") return null;
    const normalized = value.trim().toLowerCase();
    if (normalized === "cash" || normalized === "cart" || normalized === "bitcoin" || normalized === "jcmoves" || normalized === "jcmoves_usd") {
      return normalized;
    }
    return null;
  }

  function isInternalTipMethod(method: TipMethod): boolean {
    return method === "jcmoves" || method === "jcmoves_usd";
  }

  function tipCurrency(method: TipMethod): string {
    if (method === "jcmoves") return "JCMOVES";
    if (method === "jcmoves_usd") return "JCMOVES_USD";
    if (method === "bitcoin") return "BTC";
    return "USD";
  }

  function parsePositiveAmount(value: unknown): number {
    const parsed = typeof value === "number" ? value : Number(value);
    if (!Number.isFinite(parsed) || parsed <= 0) return 0;
    return parsed;
  }

  function roundMoney(value: number): number {
    return Math.round(value * 100) / 100;
  }

  function roundTokens(value: number): number {
    return Math.round(value * 100000000) / 100000000;
  }

  async function normalizeReviewTipAllocations(lead: any, body: any, method: TipMethod): Promise<NormalizedTipAllocation[]> {
    const crewIds = getReviewCrewIds(lead);
    const crewMembers = await getReviewCrewMembers(lead);
    const crewNameById = new Map(crewMembers.map((member) => [member.id, member.name]));
    const allowedCrewIds = new Set(crewIds);
    const allocations: NormalizedTipAllocation[] = [];
    const rawAllocations = Array.isArray(body?.tipAllocations) ? body.tipAllocations : [];

    for (const raw of rawAllocations) {
      const workerId = String(raw?.workerId || "").trim();
      if (!workerId || !allowedCrewIds.has(workerId)) continue;
      const amountUsd = method === "jcmoves" ? 0 : roundMoney(parsePositiveAmount(raw?.amountUsd ?? raw?.amount));
      const tokenAmount = method === "jcmoves" ? roundTokens(parsePositiveAmount(raw?.tokenAmount ?? raw?.tokens ?? raw?.amount)) : 0;
      if (method === "jcmoves" ? tokenAmount <= 0 : amountUsd <= 0) continue;
      allocations.push({
        workerId,
        workerName: crewNameById.get(workerId) || (typeof raw?.workerName === "string" ? raw.workerName.trim() : null),
        amountUsd,
        tokenAmount,
      });
    }

    if (allocations.length > 0) {
      const seen = new Set<string>();
      return allocations.filter((allocation) => {
        if (seen.has(allocation.workerId)) return false;
        seen.add(allocation.workerId);
        return true;
      });
    }

    if (crewIds.length === 0) return [];

    if (method === "jcmoves") {
      const perMoverTokens = roundTokens(parsePositiveAmount(body?.tokenTipPerMover ?? body?.tipTokenPerMover ?? body?.tokenAmountPerMover));
      if (perMoverTokens <= 0) return [];
      return crewIds.map((workerId) => ({
        workerId,
        workerName: crewNameById.get(workerId) || null,
        amountUsd: 0,
        tokenAmount: perMoverTokens,
      }));
    }

    const explicitPerMover = parsePositiveAmount(body?.tipPerMover);
    const totalUsd = roundMoney(parsePositiveAmount(body?.tipAmount));
    const perMoverUsd = roundMoney(explicitPerMover || (totalUsd > 0 ? totalUsd / crewIds.length : 0));
    if (perMoverUsd <= 0) return [];
    return crewIds.map((workerId) => ({
      workerId,
      workerName: crewNameById.get(workerId) || null,
      amountUsd: perMoverUsd,
      tokenAmount: 0,
    }));
  }

  async function ensureWalletAccountInTx(tx: any, userId: string): Promise<void> {
    await tx.insert(walletAccounts).values({ userId }).onConflictDoNothing();
  }

  async function createReviewTipAllocationsInTx(
    tx: any,
    args: {
      lead: any;
      review: any;
      body: any;
      customerUserId: string | null;
      authenticatedUserId: string | null;
    },
  ) {
    const method = normalizeTipMethod(args.body?.tipMethod);
    if (!method) {
      return { method: null, status: "none", allocations: [], totalUsd: 0, totalTokens: 0 };
    }

    const allocations = await normalizeReviewTipAllocations(args.lead, args.body, method);
    const totalUsd = roundMoney(allocations.reduce((sum, allocation) => sum + allocation.amountUsd, 0));
    const totalTokens = roundTokens(allocations.reduce((sum, allocation) => sum + allocation.tokenAmount, 0));

    if (allocations.length === 0) {
      if (isInternalTipMethod(method)) {
        throw new ReviewTipError(400, "Select at least one assigned mover before tipping with JCMOVES.");
      }
      return { method, status: "legacy_unallocated", allocations: [], totalUsd, totalTokens };
    }

    const now = new Date();
    const baseRows = allocations.map((allocation) => ({
      reviewId: args.review.id,
      leadId: args.lead.id,
      customerUserId: args.customerUserId,
      workerId: allocation.workerId,
      workerName: allocation.workerName,
      tipMethod: method,
      currency: tipCurrency(method),
      amountUsd: allocation.amountUsd.toFixed(2),
      tokenAmount: allocation.tokenAmount.toFixed(8),
      metadata: {
        reviewId: args.review.id,
        leadId: args.lead.id,
        source: "review_page_tip",
      },
    }));

    if (!isInternalTipMethod(method)) {
      const inserted = await tx.insert(reviewTipAllocations).values(
        baseRows.map((row) => ({
          ...row,
          status: "pending_payment",
          confirmedAt: null,
        })),
      ).returning();
      return { method, status: "pending_payment", allocations: inserted, totalUsd, totalTokens };
    }

    if (!args.customerUserId) {
      throw new ReviewTipError(401, "Sign in to use JCMOVES wallet tipping.");
    }
    if (!args.authenticatedUserId) {
      throw new ReviewTipError(401, "Sign in to use JCMOVES wallet tipping.");
    }
    if (args.authenticatedUserId !== args.customerUserId) {
      throw new ReviewTipError(403, "Use the customer account tied to this job to tip with JCMOVES.");
    }

    await ensureWalletAccountInTx(tx, args.customerUserId);
    for (const allocation of allocations) {
      await ensureWalletAccountInTx(tx, allocation.workerId);
    }

    if (method === "jcmoves") {
      const debitRows = await tx
        .update(walletAccounts)
        .set({
          tokenBalance: sql`COALESCE(${walletAccounts.tokenBalance}, '0')::numeric - ${totalTokens.toFixed(8)}::numeric`,
          lastActivity: now,
        })
        .where(and(
          eq(walletAccounts.userId, args.customerUserId),
          sql`COALESCE(${walletAccounts.tokenBalance}, '0')::numeric >= ${totalTokens.toFixed(8)}::numeric`,
        ))
        .returning({ tokenBalance: walletAccounts.tokenBalance });
      if (debitRows.length === 0) {
        throw new ReviewTipError(400, "Insufficient JCMOVES balance for this crew tip.");
      }

      const inserted = [];
      for (const row of baseRows) {
        const amount = Number(row.tokenAmount);
        await tx
          .update(walletAccounts)
          .set({
            tokenBalance: sql`COALESCE(${walletAccounts.tokenBalance}, '0')::numeric + ${amount.toFixed(8)}::numeric`,
            totalEarned: sql`COALESCE(${walletAccounts.totalEarned}, '0')::numeric + ${amount.toFixed(8)}::numeric`,
            lastActivity: now,
          })
          .where(eq(walletAccounts.userId, row.workerId));
        const [allocation] = await tx.insert(reviewTipAllocations).values({
          ...row,
          status: "confirmed",
          confirmedAt: now,
        }).returning();
        inserted.push(allocation);
        await tx.insert(rewards).values({
          userId: row.workerId,
          rewardType: "crew_tip_jcmoves",
          tokenAmount: amount.toFixed(8),
          cashValue: "0.00",
          status: "confirmed",
          earnedDate: now,
          referenceId: allocation.id,
          metadata: {
            reviewId: args.review.id,
            leadId: args.lead.id,
            customerUserId: args.customerUserId,
            source: "review_tip",
          },
        });
      }
      return { method, status: "confirmed", allocations: inserted, totalUsd, totalTokens };
    }

    const debitRows = await tx
      .update(walletAccounts)
      .set({
        cashBalance: sql`COALESCE(${walletAccounts.cashBalance}, '0')::numeric - ${totalUsd.toFixed(2)}::numeric`,
        lastActivity: now,
      })
      .where(and(
        eq(walletAccounts.userId, args.customerUserId),
        sql`COALESCE(${walletAccounts.cashBalance}, '0')::numeric >= ${totalUsd.toFixed(2)}::numeric`,
      ))
      .returning({ cashBalance: walletAccounts.cashBalance });
    if (debitRows.length === 0) {
      throw new ReviewTipError(400, "Insufficient JCMOVES USD balance for this crew tip.");
    }

    const inserted = [];
    for (const row of baseRows) {
      const amount = Number(row.amountUsd);
      await tx
        .update(walletAccounts)
        .set({
          cashBalance: sql`COALESCE(${walletAccounts.cashBalance}, '0')::numeric + ${amount.toFixed(2)}::numeric`,
          lastActivity: now,
        })
        .where(eq(walletAccounts.userId, row.workerId));
      const [allocation] = await tx.insert(reviewTipAllocations).values({
        ...row,
        status: "confirmed",
        confirmedAt: now,
      }).returning();
      inserted.push(allocation);
      await tx.insert(rewards).values({
        userId: row.workerId,
        rewardType: "crew_tip_jcmoves_usd",
        tokenAmount: "0.00000000",
        cashValue: amount.toFixed(2),
        status: "confirmed",
        earnedDate: now,
        referenceId: allocation.id,
        metadata: {
          reviewId: args.review.id,
          leadId: args.lead.id,
          customerUserId: args.customerUserId,
          source: "review_tip",
        },
      });
    }
    return { method, status: "confirmed", allocations: inserted, totalUsd, totalTokens };
  }

  app.post("/api/review/lookup", async (req, res) => {
    try {
      const { search } = req.body; // phone, email, or job ID
      if (!search || search.trim().length < 3) {
        return res.status(400).json({ error: "Please enter at least 3 characters" });
      }
      const q = search.trim().toLowerCase();

      // Try exact job ID first
      let matchedLeads: any[] = [];
      try {
        const byId = await storage.getLead(q);
        if (byId) matchedLeads = [byId];
      } catch {}

      // If not found by ID, search by phone or email
      if (matchedLeads.length === 0) {
        matchedLeads = await db.select().from(leads)
          .where(or(
            ilike(leads.phone, `%${q}%`),
            ilike(leads.email, `%${q}%`),
            ilike(leads.firstName, `%${q}%`),
            ilike(leads.lastName, `%${q}%`),
          ))
          .orderBy(desc(leads.createdAt))
          .limit(5);
      }

      if (matchedLeads.length === 0) {
        return res.status(404).json({ error: "No jobs found matching that information" });
      }

      // Return summary for each matching lead
      const results = matchedLeads.map((l: any) => ({
        id: l.id,
        firstName: l.firstName,
        lastName: l.lastName,
        serviceType: l.serviceType,
        status: l.status,
        createdAt: l.createdAt,
        reviewToken: l.reviewToken || null,
        hasReviewToken: !!l.reviewToken,
        isCompleted: l.status === 'completed',
      }));
      res.json({ results });
    } catch (err) {
      console.error("Review lookup error:", err);
      res.status(500).json({ error: "Lookup failed. Please try again." });
    }
  });

  // GET: Admin A-Z Pipeline view — all jobs with lifecycle stages
  app.get("/api/admin/pipeline", async (req: any, res) => {
    if (!req.session?.userId) return res.status(401).json({ error: "Unauthorized" });
    try {
      const { search, status, limit: lim = 100, offset: off = 0 } = req.query;
      let query = db.select().from(leads);
      const conditions: any[] = [];
      if (status && status !== 'all') conditions.push(eq(leads.status, status as string));
      if (search) {
        const q = `%${search}%`;
        conditions.push(or(
          ilike(leads.firstName, q), ilike(leads.lastName, q),
          ilike(leads.email, q), ilike(leads.phone, q),
        ));
      }
      const allLeads = await db.select().from(leads)
        .where(conditions.length ? and(...conditions) : undefined)
        .orderBy(desc(leads.createdAt))
        .limit(Number(lim))
        .offset(Number(off));

      // Fetch reviews for all lead IDs
      const leadIds = allLeads.map((l: any) => l.id);
      let reviewMap: Record<string, any> = {};
      if (leadIds.length > 0) {
        const allReviews = await db.select().from(reviews).where(
          leadIds.length === 1
            ? eq(reviews.leadId, leadIds[0])
            : or(...leadIds.map((id: string) => eq(reviews.leadId, id)))
        );
        for (const r of allReviews) {
          reviewMap[r.leadId] = r;
        }
      }

      // Fetch employee names for assigned employees
      const assignedIds = [...new Set(allLeads.map((l: any) => l.assignedToUserId).filter(Boolean))];
      let employeeMap: Record<string, string> = {};
      for (const eid of assignedIds) {
        try {
          const emp = await storage.getUser(eid as string);
          if (emp) employeeMap[eid as string] = `${emp.firstName || ''} ${emp.lastName || ''}`.trim();
        } catch {}
      }

      const pipeline = allLeads.map((l: any) => {
        const review = reviewMap[l.id];
        const stages = {
          quoteRequested: { done: true, at: l.createdAt },
          contacted: { done: !['new', 'quote_requested'].includes(l.status), at: null },
          assigned: { done: !!l.assignedToUserId, at: null },
          completed: { done: l.status === 'completed', at: null },
          reviewSent: { done: !!l.reviewRequestSentAt, at: l.reviewRequestSentAt },
          reviewReceived: { done: !!review, at: review?.createdAt || null },
        };
        return {
          id: l.id,
          firstName: l.firstName,
          lastName: l.lastName,
          email: l.email,
          phone: l.phone,
          serviceType: l.serviceType,
          status: l.status,
          createdAt: l.createdAt,
          assignedEmployee: l.assignedToUserId ? (employeeMap[l.assignedToUserId] || 'Assigned') : null,
          reviewToken: l.reviewToken,
          reviewRequestSentAt: l.reviewRequestSentAt,
          review: review ? {
            id: review.id, rating: review.rating, comment: review.comment,
            tipAmount: review.tipAmount, wouldRecommend: review.wouldRecommend,
            createdAt: review.createdAt,
          } : null,
          stages,
        };
      });

      const totalCount = await db.select({ count: sql<number>`count(*)` }).from(leads)
        .where(conditions.length ? and(...conditions) : undefined);

      res.json({ pipeline, total: Number(totalCount[0]?.count || 0) });
    } catch (err) {
      console.error("Pipeline fetch error:", err);
      res.status(500).json({ error: err instanceof Error ? err.message : "Failed to load pipeline" });
    }
  });

