  // Employee Job Routes
  // Helper: enrich leads list by backfilling phone from the user table when lead.phone is blank
  async function enrichLeadsWithPhone(leadList: any[]): Promise<any[]> {
    const missing = leadList.filter(l => !l.phone && l.email);
    if (missing.length === 0) return leadList;
    const emails = [...new Set(missing.map(l => l.email as string))];
    const matchedUsers = await db.select({ email: users.email, phoneNumber: users.phoneNumber })
      .from(users)
      .where(inArray(users.email, emails));
    const phoneMap: Record<string, string> = {};
    for (const u of matchedUsers) {
      if (u.email && u.phoneNumber) phoneMap[u.email] = u.phoneNumber;
    }
    return leadList.map(l => ({
      ...l,
      phone: l.phone || phoneMap[l.email] || null,
    }));
  }

  const isBusinessOwnerUser = (user: any) => Boolean(
    user && (["admin", "business_owner"].includes(String(user.role || "")) || user.email === "upmichiganstatemovers@gmail.com"),
  );

  const workerOrderContextForRecord = (record: any, userId: string): "claimed" | "assigned" => {
    const accepted = Array.isArray(record.acceptedByEmployees) && record.acceptedByEmployees.includes(userId);
    const directlyAssigned = record.assignedToUserId === userId;
    const dispatchState = String(record.dispatchState || "").toLowerCase();
    const formallyDispatched = ["assigned", "accepted", "en_route", "on_site", "in_progress", "completed"].includes(dispatchState);
    return accepted || directlyAssigned || formallyDispatched ? "assigned" : "claimed";
  };

  const presentJobFlowRecord = (
    record: any,
    user: any,
    includeAccess: boolean,
    authorityTier: WorkerTier = "worker",
    context?: Exclude<WorkerOrderContext, "board">,
  ) => {
    const { accessInstructionsCiphertext, ...safeRecord } = record;
    const visibleRecord = {
      ...safeRecord,
      ...(includeAccess ? { jobAccess: decryptJobAccessDetails(accessInstructionsCiphertext) } : {}),
    };
    const resolvedContext = context || (isBusinessOwnerUser(user)
      ? "admin"
      : jobBelongsToCrew(record, user.id)
        ? workerOrderContextForRecord(record, user.id)
        : "task");
    return projectWorkerOrder(visibleRecord, authorityTier, resolvedContext);
  };

  const presentJobFlowRecordWithEarnings = async (
    record: any,
    user: any,
    includeAccess: boolean,
    authorityTier: WorkerTier = "worker",
    context?: Exclude<WorkerOrderContext, "board">,
  ) => ({
    ...presentJobFlowRecord(record, user, includeAccess, authorityTier, context),
    personalEarnings: jobBelongsToCrew(record, user.id)
      ? await buildPersonalEarningsForLead(record, user.id)
      : null,
  });

  const isCrewBoardEligible = (record: Awaited<ReturnType<typeof buildJobFlowRecords>>[number]) => {
    const status = String(record.status || "").toLowerCase();
    return ["available", "open"].includes(status)
      && ["ready_for_crew", "crew_claimed"].includes(record.flow.stage)
      && record.flow.crew.openSlots > 0;
  };

  const isPlannerActive = (record: Awaited<ReturnType<typeof buildJobFlowRecords>>[number]) => {
    const status = String(record.status || "").toLowerCase();
    return !record.archivedAt && !["completed", "paid", "cancelled", "closed"].includes(status);
  };

  const canViewJobTask = async (user: any, record: Awaited<ReturnType<typeof buildJobFlowRecords>>[number]) => {
    if (isBusinessOwnerUser(user) || jobBelongsToCrew(record, user.id) || isCrewBoardEligible(record)) return true;

    const authority = await getWorkerAuthority(user);
    const status = String(record.status || "").toLowerCase();
    const quoteTaskStatus = ["new", "contacted", "quote_requested", "chatbot_pending", "pending_quote_approval", "quoted"].includes(status);
    const approvalTaskStatus = ["quote_requested", "chatbot_pending", "pending_quote_approval", "quoted"].includes(status);

    return (authority.rank >= tierRank.silver && quoteTaskStatus)
      || (authority.rank >= tierRank.gold && approvalTaskStatus);
  };

  const decorateCrewBoardRecords = async (records: Awaited<ReturnType<typeof buildJobFlowRecords>>, user: any) => {
    const { calcCrewBonus } = await import("@shared/crewIncentives");
    const authority = await getWorkerAuthority(user);
    const FLAT_TOKEN_BASE = 500;
    const TOKENS_PER_HOUR = 25;
    const DEFAULT_HOURS = 3;
    return records.map((record) => {
      const boardRecord = toCrewBoardFlow(record, user.id, authority.authorityTier);
      const estimatedHrs = record.confirmedHours || DEFAULT_HOURS;
      return {
        ...boardRecord,
        estimatedTokens: FLAT_TOKEN_BASE + TOKENS_PER_HOUR * estimatedHrs,
        bonus: calcCrewBonus({
          urgency: record.urgency,
          arrivalWindow: record.arrivalWindow,
          moveDate: record.moveDate,
          confirmedDate: record.confirmedDate,
          crewSize: record.crewSize,
          crewSlotsFilled: record.flow.crew.claimed,
          totalPrice: record.totalPrice,
          serviceType: record.serviceType,
        }),
      };
    });
  };

  /**
   * One canonical job feed.  It intentionally returns the same lead record
   * shape that legacy screens expect, augmented with `flow`, so individual
   * pages can migrate without changing payments, dispatch, or payout APIs.
   */
  app.get("/api/jobs/flow", isAuthenticated, requireEmployee, async (req: any, res) => {
    try {
      const scope = String(req.query.scope || "mine");
      if (!["admin", "board", "mine"].includes(scope)) {
        return res.status(400).json({ error: "scope must be admin, board, or mine" });
      }
      const user = req.currentUser;
      if (scope === "admin" && !isBusinessOwnerUser(user)) {
        return res.status(403).json({ error: "Business owner access required" });
      }

      const allRecords = await buildJobFlowRecords(await storage.getLeads());
      if (scope === "admin") return res.json(allRecords.map((record) => presentJobFlowRecord(record, user, true, "platinum", "admin")));
      if (scope === "board") {
        return res.json(await decorateCrewBoardRecords(allRecords.filter(isCrewBoardEligible), user));
      }
      const authority = await getWorkerAuthority(user);
      return res.json(await Promise.all(allRecords
        .filter((record) => jobBelongsToCrew(record, user.id))
        .map((record) => presentJobFlowRecordWithEarnings(record, user, true, authority.authorityTier))));
    } catch (error) {
      console.error("Error fetching universal job flow:", error);
      res.status(500).json({ error: "Failed to fetch job flow" });
    }
  });

  app.patch("/api/employees/:id/payout-profile", isAuthenticated, requireBusinessOwner, async (req: any, res) => {
    try {
      const role = normalizePayoutRole(req.body?.payoutClassification);
      const settings = rowToProfitShareSettings(await getDefaultPayoutSettings());
      const defaultWeight = defaultBonusWeightForRole(role, settings);
      const requestedWeight = req.body?.defaultBonusWeight === undefined
        ? defaultWeight
        : numberFrom(req.body.defaultBonusWeight, defaultWeight);
      if (requestedWeight < 0 || requestedWeight > 100) {
        return res.status(400).json({ error: "Default profit weight must be between 0 and 100." });
      }
      const [employee] = await db.select({ id: users.id }).from(users).where(eq(users.id, req.params.id)).limit(1);
      if (!employee) return res.status(404).json({ error: "Employee not found" });
      const [profile] = await db.insert(workerProfiles).values({
        userId: employee.id,
        payoutClassification: role,
        defaultBonusWeight: dbRatio(requestedWeight),
        updatedAt: new Date(),
      }).onConflictDoUpdate({
        target: workerProfiles.userId,
        set: {
          payoutClassification: role,
          defaultBonusWeight: dbRatio(requestedWeight),
          updatedAt: new Date(),
        },
      }).returning();
      res.json(profile);
    } catch (error) {
      console.error("Error updating employee payout profile:", error);
      res.status(500).json({ error: "Failed to update employee payout profile" });
    }
  });

  // Calendar-first operational feed. Every visible record carries the same flow
  // projection used by job details so the planner and job workspace cannot drift.
  app.get("/api/jobs/planner", isAuthenticated, requireEmployee, async (req: any, res) => {
    try {
      const user = req.currentUser;
      const records = (await buildJobFlowRecords(await storage.getLeads())).filter(isPlannerActive);
      const isAdmin = isBusinessOwnerUser(user);
      const visible = isAdmin
        ? records
        : (await Promise.all(records.map(async (record) => (
          await canViewJobTask(user, record) ? record : null
        )))).filter(Boolean);

      const authority = isAdmin ? null : await getWorkerAuthority(user);

      const items = isAdmin
        ? visible.map((record: any) => presentJobFlowRecord(record, user, true, "platinum", "admin"))
        : await Promise.all(visible.map((record: any) => jobBelongsToCrew(record, user.id)
          ? presentJobFlowRecordWithEarnings(record, user, true, authority!.authorityTier)
          : isCrewBoardEligible(record)
            ? toCrewBoardFlow(record, user.id, authority!.authorityTier)
            : presentJobFlowRecord(record, user, false, authority!.authorityTier, "task")));
      res.json({
        items,
        viewer: {
          isAdmin,
          canAddJob: isAdmin,
        },
      });
    } catch (error) {
      console.error("Error fetching job planner:", error);
      res.status(500).json({ error: "Failed to fetch job planner" });
    }
  });

  app.get("/api/jobs/:id/flow", isAuthenticated, requireEmployee, async (req: any, res) => {
    try {
      const user = req.currentUser;
      const lead = await storage.getLead(req.params.id);
      if (!lead || lead.archivedAt) return res.status(404).json({ error: "Job not found" });
      const [record] = await buildJobFlowRecords([lead]);
      if (isBusinessOwnerUser(user) || jobBelongsToCrew(record, user.id)) {
        const isOwner = isBusinessOwnerUser(user);
        const authorityTier = isOwner ? "platinum" : (await getWorkerAuthority(user)).authorityTier;
        return res.json(await presentJobFlowRecordWithEarnings(record, user, true, authorityTier, isOwner ? "admin" : undefined));
      }
      if (isCrewBoardEligible(record)) return res.json((await decorateCrewBoardRecords([record], user))[0]);
      if (await canViewJobTask(user, record)) {
        const authority = await getWorkerAuthority(user);
        return res.json(presentJobFlowRecord(record, user, false, authority.authorityTier, "task"));
      }
      return res.status(403).json({ error: "Access denied" });
    } catch (error) {
      console.error("Error fetching universal job detail:", error);
      res.status(500).json({ error: "Failed to fetch job detail" });
    }
  });

  // Worker claim keeps the provisional crew on the canonical lead record.
  // `acceptedByEmployees` remains untouched until the formal dispatch offer
  // is accepted, so Admin can see the difference between a claim and a job
  // that has actually been dispatched.
  const handleCrewClaim = async (req: any, res: any) => {
    try {
      const leadId = req.params.id;
      const userId = req.currentUser.id;

      const [lead] = await db.select().from(leads).where(eq(leads.id, leadId));
      if (!lead) return res.status(404).json({ error: "Job not found" });

      if (["completed", "cancelled"].includes(lead.status)) {
        return res.status(400).json({ error: "This job is no longer open" });
      }

      const [flowRecord] = await buildJobFlowRecords([lead]);
      if (!isCrewBoardEligible(flowRecord)) {
        return res.status(409).json({
          error: "This job is not ready for crew claims",
          code: "JOB_NOT_READY_FOR_CLAIM",
          flow: flowRecord.flow,
        });
      }

      const currentMembers: string[] = Array.isArray(lead.crewMembers) ? lead.crewMembers : [];
      if (currentMembers.includes(userId)) {
        return res.status(400).json({ error: "You have already signed up for this job" });
      }

      const crewSize = Math.max(1, lead.crewSize || 2);
      if (currentMembers.length >= crewSize) {
        return res.status(409).json({ error: "This crew is already full", code: "CREW_FULL" });
      }

      const updatedMembers = [...currentMembers, userId];
      const [updatedLead] = await db.update(leads)
        .set({ crewMembers: updatedMembers })
        .where(eq(leads.id, leadId))
        .returning();
      if (!updatedLead) return res.status(404).json({ error: "Job not found" });

      await emitJobEvent("crew_claimed", updatedLead, {
        actorId: userId,
        source: "crew_claim",
        note: "Crew member claimed an open job slot.",
        extra: { claimedByUserId: userId, claimedSlots: updatedMembers.length, crewSize },
      });

      const [updatedFlow] = await buildJobFlowRecords([updatedLead]);

      res.json({
        success: true,
        message: "Claimed — Admin will confirm the crew and dispatch the job.",
        job: updatedFlow,
      });
    } catch (error) {
      console.error("Error applying to job:", error);
      res.status(500).json({ error: "Failed to sign up for job" });
    }
  };

  app.post("/api/jobs/:id/claim", isAuthenticated, requireEmployee, handleCrewClaim);
  // Legacy client compatibility. Both paths call the same canonical command.
  app.post("/api/leads/:id/crew-apply", isAuthenticated, requireEmployee, handleCrewClaim);

  // ── Trade Requests ─────────────────────────────────────────────────────────

  // Core handler for trade request creation — used by both route aliases below
  const handleTradeRequestCreate = async (req: any, res: any) => {
    try {
      const leadId = req.params.id;
      const requesterId = req.currentUser.id;
      const { targetId, requesterNote } = req.body;

      if (!targetId || typeof targetId !== "string") {
        return res.status(400).json({ error: "targetId is required" });
      }
      if (targetId === requesterId) {
        return res.status(400).json({ error: "Cannot trade a job with yourself" });
      }

      const [lead] = await db.select().from(leads).where(eq(leads.id, leadId));
      if (!lead) return res.status(404).json({ error: "Job not found" });

      if (["completed", "cancelled"].includes(lead.status)) {
        return res.status(400).json({ error: "Cannot trade a completed or cancelled job" });
      }

      const crewMembers: string[] = Array.isArray(lead.crewMembers) ? lead.crewMembers : [];

      if (!crewMembers.includes(requesterId)) {
        return res.status(403).json({ error: "You are not assigned to this job" });
      }

      if (crewMembers.includes(targetId)) {
        return res.status(400).json({ error: "Target worker is already on this job's crew" });
      }

      // Verify target user exists and is an eligible approved employee
      const [targetUser] = await db.select({ id: users.id, status: users.status, role: users.role })
        .from(users)
        .where(eq(users.id, targetId))
        .limit(1);

      if (!targetUser) {
        return res.status(404).json({ error: "Target worker not found" });
      }
      if (targetUser.status !== "approved" && targetUser.role !== "admin") {
        return res.status(400).json({ error: "Target worker is not an eligible crew member" });
      }

      // Check for existing pending request for this job by this requester
      const existing = await db.select().from(jobTradeRequests)
        .where(and(
          eq(jobTradeRequests.leadId, leadId),
          eq(jobTradeRequests.requesterId, requesterId),
          eq(jobTradeRequests.status, "pending")
        )).limit(1);

      if (existing.length > 0) {
        return res.status(400).json({ error: "You already have a pending trade request for this job" });
      }

      const [inserted] = await db.insert(jobTradeRequests).values({
        leadId,
        requesterId,
        targetId,
        requesterNote: requesterNote || null,
      }).returning();

      res.json({ success: true, tradeRequest: inserted });
    } catch (error) {
      console.error("Error creating trade request:", error);
      res.status(500).json({ error: "Failed to submit trade request" });
    }
  };

  // POST /api/leads/:id/trade-request — request to trade a job slot (primary path)
  app.post("/api/leads/:id/trade-request", isAuthenticated, requireEmployee, handleTradeRequestCreate);

  // POST /api/jobs/:id/trade-request — alias for consistency with task spec
  app.post("/api/jobs/:id/trade-request", isAuthenticated, requireEmployee, handleTradeRequestCreate);

  // GET /api/trade-requests/my — worker's own trade requests
  app.get("/api/trade-requests/my", isAuthenticated, requireEmployee, async (req: any, res) => {
    try {
      const userId = req.currentUser.id;
      const rows = await db.select().from(jobTradeRequests)
        .where(or(
          eq(jobTradeRequests.requesterId, userId),
          eq(jobTradeRequests.targetId, userId)
        ))
        .orderBy(desc(jobTradeRequests.createdAt))
        .limit(50);
      res.json(rows);
    } catch (error) {
      console.error("Error fetching my trade requests:", error);
      res.status(500).json({ error: "Failed to fetch trade requests" });
    }
  });

  // GET /api/trade-requests — admin: all trade requests with enriched data
  app.get("/api/trade-requests", isAuthenticated, requireBusinessOwner, async (req: any, res) => {
    try {
      const rows = await db.select().from(jobTradeRequests)
        .orderBy(desc(jobTradeRequests.createdAt))
        .limit(200);

      // Enrich with user names and job info
      const userIds = [...new Set(rows.flatMap(r => [r.requesterId, r.targetId]))];
      const leadIds = [...new Set(rows.map(r => r.leadId))];

      const [usersData, leadsData] = await Promise.all([
        userIds.length > 0
          ? db.select({ id: users.id, firstName: users.firstName, lastName: users.lastName })
              .from(users).where(inArray(users.id, userIds))
          : Promise.resolve([]),
        leadIds.length > 0
          ? db.select({ id: leads.id, firstName: leads.firstName, lastName: leads.lastName, serviceType: leads.serviceType, moveDate: leads.moveDate, fromAddress: leads.fromAddress })
              .from(leads).where(inArray(leads.id, leadIds))
          : Promise.resolve([]),
      ]);

      const userMap = Object.fromEntries(usersData.map(u => [u.id, u]));
      const leadMap = Object.fromEntries(leadsData.map(l => [l.id, l]));

      const enriched = rows.map(r => ({
        ...r,
        requester: userMap[r.requesterId] ?? null,
        target: userMap[r.targetId] ?? null,
        job: leadMap[r.leadId] ?? null,
      }));

      res.json(enriched);
    } catch (error) {
      console.error("Error fetching trade requests:", error);
      res.status(500).json({ error: "Failed to fetch trade requests" });
    }
  });

  // PATCH /api/trade-requests/:id/review — admin approve or deny a trade request
  app.patch("/api/trade-requests/:id/review", isAuthenticated, requireBusinessOwner, async (req: any, res) => {
    try {
      const { id } = req.params;
      const { status, adminNote } = req.body;
      const adminId = req.currentUser.id;

      if (!["approved", "denied"].includes(status)) {
        return res.status(400).json({ error: "status must be 'approved' or 'denied'" });
      }

      const [tradeReq] = await db.select().from(jobTradeRequests).where(eq(jobTradeRequests.id, id));
      if (!tradeReq) return res.status(404).json({ error: "Trade request not found" });
      if (tradeReq.status !== "pending") {
        return res.status(400).json({ error: "Trade request has already been reviewed" });
      }

      await db.update(jobTradeRequests)
        .set({ status, adminNote: adminNote || null, reviewedByUserId: adminId, reviewedAt: new Date() })
        .where(eq(jobTradeRequests.id, id));

      // If approved, swap crew members on the lead (deduplicate to prevent double-adds)
      if (status === "approved") {
        const [lead] = await db.select().from(leads).where(eq(leads.id, tradeReq.leadId));
        if (lead) {
          // Guard: do not mutate crew on jobs that are already completed or cancelled
          if (["completed", "cancelled"].includes(lead.status)) {
            return res.status(400).json({
              error: "Cannot approve a trade for a job that is already completed or cancelled"
            });
          }
          const crewMembers: string[] = Array.isArray(lead.crewMembers) ? lead.crewMembers : [];
          const newCrew = [...new Set(
            crewMembers
              .filter(m => m !== tradeReq.requesterId)
              .concat(tradeReq.targetId)
          )];
          await db.update(leads)
            .set({ crewMembers: newCrew })
            .where(eq(leads.id, tradeReq.leadId));
        }
      }

      res.json({ success: true, status });
    } catch (error) {
      console.error("Error reviewing trade request:", error);
      res.status(500).json({ error: "Failed to review trade request" });
    }
  });

