  // Get wallet balance
  app.get("/api/rewards/wallet", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user?.id || (req.session as any).userId;

      const wallet = await db
        .select()
        .from(walletAccounts)
        .where(eq(walletAccounts.userId, userId))
        .limit(1);

      const [earnedRow] = await db
        .select({
          totalEarned: sql<number>`coalesce(sum(case when cast(${rewards.tokenAmount} as decimal) > 0 then cast(${rewards.tokenAmount} as decimal) else 0 end), 0)`,
        })
        .from(rewards)
        .where(and(
          eq(rewards.userId, userId),
          eq(rewards.status, "confirmed"),
        ));

      const [redeemedRow] = await db
        .select({
          totalRedeemed: sql<number>`coalesce(sum(${rewardRedemptions.tokenCost}), 0)`,
        })
        .from(rewardRedemptions)
        .where(and(
          eq(rewardRedemptions.userId, userId),
          inArray(rewardRedemptions.status, ["pending", "pending_approval", "approved", "redeemed_pending_schedule", "completed"]),
        ));

      const recoveredTotalEarned = Number(earnedRow?.totalEarned ?? 0);
      const recoveredTotalRedeemed = Number(redeemedRow?.totalRedeemed ?? 0);
      const recoveredBalance = Math.max(0, recoveredTotalEarned - recoveredTotalRedeemed);

      if (wallet.length === 0) {
        // Backfill migrated users from their existing confirmed reward history
        // so they don't appear to have a zero balance on first wallet load.
        const newWallet = await db.insert(walletAccounts).values({
          userId,
          tokenBalance: recoveredBalance.toFixed(8),
          totalEarned: recoveredTotalEarned.toFixed(8),
          totalRedeemed: recoveredTotalRedeemed.toFixed(8),
        }).returning();
        return res.json(newWallet[0]);
      }

      const existingWallet = wallet[0];
      const existingBalance = Number(existingWallet.tokenBalance ?? 0);
      const existingTotalEarned = Number(existingWallet.totalEarned ?? 0);

      if (existingBalance <= 0 && existingTotalEarned <= 0 && recoveredTotalEarned > 0) {
        const [repairedWallet] = await db
          .update(walletAccounts)
          .set({
            tokenBalance: recoveredBalance.toFixed(8),
            totalEarned: recoveredTotalEarned.toFixed(8),
            totalRedeemed: recoveredTotalRedeemed.toFixed(8),
            lastActivity: new Date(),
          })
          .where(eq(walletAccounts.userId, userId))
          .returning();
        return res.json(repairedWallet);
      }

      res.json(wallet[0]);
    } catch (error) {
      console.error("Error getting wallet:", error);
      res.status(500).json({ error: "Failed to get wallet" });
    }
  });

  // Get rewards history with pagination and server-side totals
  // Unions: rewards table + mining claims + redemptions (as spend events)
  app.get("/api/rewards/history", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user?.id || (req.session as any).userId;
      const limit = parseInt(req.query.limit as string) || 50;
      const offset = parseInt(req.query.offset as string) || 0;

      // Main rewards table (booking, completion, referral, sign-up, etc.)
      // Includes wallet_balance_redemption (USD shop-credit spends) and
      // wallet_balance_redemption_refund rows — both surfaced via cash_value.
      const { rows: rewardsRows } = await pool.query(
        `SELECT
           id::text,
           reward_type AS "rewardType",
           token_amount::text AS "tokenAmount",
           cash_value::text AS "cashValue",
           CASE
             WHEN reward_type = 'wallet_balance_redemption' THEN 'usd_spend'
             WHEN reward_type = 'wallet_balance_redemption_refund' THEN 'usd_refund'
             ELSE 'earn'
           END AS "direction",
           status,
           earned_date AS "earnedDate",
           metadata
         FROM rewards
         WHERE user_id = $1
           AND reward_type <> 'mining_claim'`,
        [userId]
      );

      // Mining claims (daily mining system)
      const { rows: miningRows } = await pool.query(
        `SELECT
           id::text,
           'daily_mining' AS "rewardType",
           token_amount::text AS "tokenAmount",
           'earn' AS "direction",
           'confirmed' AS status,
           claim_time AS "earnedDate",
           NULL AS metadata
         FROM mining_claims
         WHERE user_id = $1`,
        [userId]
      );

      // Redemptions (token spends)
      const { rows: redemptionRows } = await pool.query(
        `SELECT
           id::text,
           'redemption' AS "rewardType",
           token_cost::text AS "tokenAmount",
           'spend' AS "direction",
           status,
           created_at AS "earnedDate",
           json_build_object('itemName', item_name, 'couponCode', coupon_code) AS metadata
         FROM reward_redemptions
         WHERE user_id = $1
           AND status NOT IN ('cancelled')`,
        [userId]
      );

      // Merge and sort by earnedDate desc, apply limit + offset
      const all = [...rewardsRows, ...miningRows, ...redemptionRows].sort(
        (a, b) => new Date(b.earnedDate).getTime() - new Date(a.earnedDate).getTime()
      );
      const paginated = all.slice(offset, offset + limit);

      // Totals (earned only, not counting spends)
      const { rows: totals } = await pool.query(
        `SELECT
           (SELECT COALESCE(SUM(token_amount::numeric), 0) FROM rewards WHERE user_id = $1 AND reward_type <> 'mining_claim')
           + (SELECT COALESCE(SUM(token_amount::numeric), 0) FROM mining_claims WHERE user_id = $1)
           AS total_earned,
           (SELECT COUNT(*) FROM rewards WHERE user_id = $1 AND reward_type <> 'mining_claim')
           + (SELECT COUNT(*) FROM mining_claims WHERE user_id = $1)
           + (SELECT COUNT(*) FROM reward_redemptions WHERE user_id = $1 AND status NOT IN ('cancelled'))
           AS total_count`,
        [userId]
      );

      res.json({
        rewards: paginated,
        total: parseInt(totals[0]?.total_count || "0"),
        totalTokensEarned: (parseFloat(totals[0]?.total_earned || "0")).toFixed(2),
      });
    } catch (error) {
      console.error("Error getting rewards history:", error);
      res.status(500).json({ error: "Failed to get rewards history" });
    }
  });

