  app.post("/api/admin/analytics/booking-funnel/:id/recover", isAuthenticated, requireBusinessOwner, async (req: any, res) => {
    try {
      const eventId = Number(req.params.id);
      if (!Number.isFinite(eventId) || eventId <= 0) {
        return res.status(400).json({ error: "Invalid funnel event id" });
      }
      const { rows } = await pool.query(
        `SELECT id, visitor_id, session_id, event_type, step, lead_id, field_snapshot, created_at
           FROM booking_funnel_events
          WHERE id = $1
          LIMIT 1`,
        [eventId],
      );
      const event = rows[0];
      if (!event) return res.status(404).json({ error: "Funnel event not found" });
      if (event.lead_id) return res.status(409).json({ error: "This funnel event has already been recovered", leadId: event.lead_id });

      const snapshot = event.field_snapshot && typeof event.field_snapshot === "object" ? event.field_snapshot : {};
      const contact = snapshot.contact && typeof snapshot.contact === "object" ? snapshot.contact : {};
      const attribution = snapshot.attribution && typeof snapshot.attribution === "object" && !Array.isArray(snapshot.attribution)
        ? snapshot.attribution as Record<string, unknown>
        : {};
      const marketingTracking = safeMarketingTracking(attribution.marketingTracking);
      const promoCode = typeof attribution.promoCode === "string" ? attribution.promoCode.trim().toUpperCase() : "";
      const referralSlug = typeof attribution.referralSlug === "string" ? attribution.referralSlug.trim().toLowerCase() : "";
      const marketingCampaignId =
        typeof attribution.marketingCampaignId === "string" && attribution.marketingCampaignId.trim()
          ? attribution.marketingCampaignId.trim()
          : marketingTracking.jcCampaign || marketingTracking.utmContent || "";
      const recoveredSource =
        marketingTracking.utmSource ||
        (marketingCampaignId ? "marketing_campaign" : "booking_funnel_recovery");
      const items = Array.isArray(snapshot.items) ? snapshot.items : [];
      const firstItem = items[0] || {};
      const nameParts = String(contact.name || "Recovered Visitor").trim().split(/\s+/);
      const firstName = nameParts.shift() || "Recovered";
      const lastName = nameParts.length > 0 ? nameParts.join(" ") : "Visitor";
      const phone = String(contact.phone || "").trim() || "unknown";
      const email = String(contact.email || "").trim() || `recovered-${event.id}@jconthemove.local`;
      const serviceCode = String(firstItem.serviceCode || "moving");
      const serviceType =
        serviceCode === "junk_removal" ? "junk" :
        serviceCode === "moving" ? "residential" :
        serviceCode;
      const fromAddress =
        String(snapshot.serviceAddress || "").trim() ||
        [snapshot.city, snapshot.state, snapshot.zip].filter(Boolean).join(", ") ||
        "Recovered booking funnel request";
      const details = [
        "[RECOVERED BOOKING FUNNEL REQUEST]",
        `Funnel event: ${event.id}`,
        `Visitor: ${event.visitor_id || "unknown"}`,
        `Session: ${event.session_id || "unknown"}`,
        `Last step: ${event.step || "unknown"}`,
        `Event type: ${event.event_type}`,
        firstItem.label ? `Service: ${firstItem.label}` : null,
        firstItem.movingPath ? `Path: ${firstItem.movingPath}` : null,
        firstItem.loadType ? `Load type: ${firstItem.loadType}` : null,
        firstItem.truckNeeded != null ? `Truck: ${firstItem.truckNeeded ? "JC provides truck" : "Customer provides truck"}` : null,
        firstItem.truckSize ? `Truck size: ${firstItem.truckSize}` : null,
        firstItem.packageLabel ? `Package: ${firstItem.packageLabel}` : null,
        firstItem.crew ? `Crew: ${firstItem.crew}` : null,
        firstItem.hours ? `Hours: ${firstItem.hours}` : null,
        recoveredSource ? `Source: ${recoveredSource}` : null,
        promoCode ? `Promo code: ${promoCode}` : null,
        referralSlug ? `Referral rep: ${referralSlug}` : null,
        marketingCampaignId ? `Marketing campaign: ${marketingCampaignId}` : null,
        marketingTracking.utmCampaign ? `UTM campaign: ${marketingTracking.utmCampaign}` : null,
        marketingTracking.jcArea ? `Ad area: ${marketingTracking.jcArea}` : null,
        marketingTracking.jcFocus ? `Ad focus: ${marketingTracking.jcFocus}` : null,
        snapshot.marketplacePreview?.estimateLabel ? `Zone estimate: ${snapshot.marketplacePreview.estimateLabel}` : null,
        snapshot.continueReason ? `Last blocker: ${snapshot.continueReason}` : null,
      ].filter(Boolean).join("\n");

      const lead = await storage.createLead({
        firstName,
        lastName,
        email,
        phone,
        serviceType,
        fromAddress,
        toAddress: null,
        moveDate: firstItem.requestedDate || null,
        details,
        source: recoveredSource,
        status: "quote_requested",
        promoCode: promoCode || null,
        createdByUserId: req.user?.id || null,
        truckConfig: firstItem.truckNeeded != null ? (firstItem.truckNeeded ? "company_truck" : "customer_truck") : null,
        crewSize: Number(firstItem.crew || 2),
        confirmedHours: firstItem.hours ? Math.round(Number(firstItem.hours)) : null,
        basePrice: firstItem.minPrice ? String(firstItem.minPrice) : null,
        totalPrice: firstItem.maxPrice ? String(firstItem.maxPrice) : null,
        quoteNotes: snapshot.continueReason ? `Recovered from abandoned booking funnel. Last blocker: ${snapshot.continueReason}` : "Recovered from abandoned booking funnel.",
        lastQuoteUpdatedAt: new Date(),
        quoteSnapshot: {
          recoveredFromFunnelEventId: event.id,
          visitorId: event.visitor_id,
          sessionId: event.session_id,
          attribution: {
            source: recoveredSource,
            promoCode: promoCode || null,
            referralSlug: referralSlug || null,
            marketingCampaignId: marketingCampaignId || null,
            marketingTracking,
          },
          snapshot,
        },
        zoneSnapshot: snapshot.marketplacePreview ? { marketplaceQuotePreview: snapshot.marketplacePreview } : {},
      } as any);

      if (promoCode || referralSlug || marketingCampaignId || Object.keys(marketingTracking).length > 0) {
        try {
          let repUserId: string | null = null;
          let attributedPromoCode: string | null = promoCode || null;
          let attributedReferralSlug: string | null = referralSlug || null;
          if (promoCode || referralSlug) {
            const [rep] = await db.select().from(marketingReps)
              .where(promoCode
                ? eq(marketingReps.promoCode, promoCode)
                : eq(marketingReps.slug, referralSlug))
              .limit(1);
            if (rep) {
              attributedPromoCode = rep.promoCode || attributedPromoCode;
              attributedReferralSlug = rep.slug || attributedReferralSlug;
              const [ownedPromo] = await db.select({ referralUserId: promoCodes.referralUserId })
                .from(promoCodes)
                .where(eq(promoCodes.code, rep.promoCode))
                .limit(1);
              if (ownedPromo?.referralUserId) {
                repUserId = ownedPromo.referralUserId;
              } else {
                const [workerProfile] = await db.select({ userId: workerProfiles.userId })
                  .from(workerProfiles)
                  .where(eq(workerProfiles.promoCode, rep.promoCode))
                  .limit(1);
                repUserId = workerProfile?.userId || null;
              }
            }
          }
          await db.insert(quoteAttributions).values({
            leadId: lead.id,
            userId: repUserId,
            attributionType: attributedPromoCode || attributedReferralSlug
              ? "marketing_rep_funnel_recovery"
              : "marketing_campaign_funnel_recovery",
            promoCode: attributedPromoCode,
            metadata: {
              source: recoveredSource,
              referralSlug: attributedReferralSlug,
              marketingCampaignId: marketingCampaignId || null,
              marketingTracking,
              recoveredFromFunnelEventId: event.id,
              visitorId: event.visitor_id || null,
              sessionId: event.session_id || null,
              funnelStep: event.step || null,
            },
          });
        } catch (attrErr) {
          console.error("[admin/booking-funnel/recover] marketing attribution failed:", attrErr instanceof Error ? attrErr.message : attrErr);
        }
      }

      await pool.query(
        `UPDATE booking_funnel_events SET lead_id = $1 WHERE id = $2`,
        [lead.id, event.id],
      );
      await emitJobEvent("quote_requested", lead, {
        actorId: req.user?.id || null,
        source: "booking_funnel_recovery",
        extra: {
          displayOrderNumber: formatOrderNumber(lead.orderNumber),
          recoveredFromFunnelEventId: event.id,
          source: recoveredSource,
          promoCode: promoCode || null,
          referralSlug: referralSlug || null,
          marketingCampaignId: marketingCampaignId || null,
          marketingTracking,
        },
      });
      return res.json({ success: true, lead });
    } catch (err) {
      console.error("[admin/booking-funnel/recover] error:", err);
      return res.status(500).json({ error: "Failed to recover funnel request" });
    }
  });

  app.get("/api/admin/analytics/traffic", isAuthenticated, requireBusinessOwner, async (req, res) => {
    try {
      const { rows: monthly } = await pool.query(`
        SELECT
          TO_CHAR(visited_at, 'YYYY-MM') AS month,
          COUNT(*) AS total_views,
          COUNT(DISTINCT visitor_id) AS unique_visitors
        FROM page_views
        WHERE visited_at >= NOW() - INTERVAL '12 months'
        GROUP BY TO_CHAR(visited_at, 'YYYY-MM')
        ORDER BY month DESC
        LIMIT 12
      `);

      const { rows: topPages } = await pool.query(`
        SELECT
          page,
          COUNT(*) AS views,
          COUNT(DISTINCT visitor_id) AS unique_visitors
        FROM page_views
        WHERE visited_at >= DATE_TRUNC('month', NOW())
        GROUP BY page
        ORDER BY views DESC
        LIMIT 10
      `);

      const { rows: daily } = await pool.query(`
        SELECT
          TO_CHAR(visited_at, 'YYYY-MM-DD') AS day,
          COUNT(*) AS views,
          COUNT(DISTINCT visitor_id) AS unique_visitors
        FROM page_views
        WHERE visited_at >= DATE_TRUNC('month', NOW())
        GROUP BY TO_CHAR(visited_at, 'YYYY-MM-DD')
        ORDER BY day ASC
      `);

      const { rows: totals } = await pool.query(`
        SELECT
          COUNT(*) AS all_time_views,
          COUNT(DISTINCT visitor_id) AS all_time_unique,
          COUNT(*) FILTER (WHERE visited_at >= DATE_TRUNC('month', NOW())) AS this_month_views,
          COUNT(DISTINCT visitor_id) FILTER (WHERE visited_at >= DATE_TRUNC('month', NOW())) AS this_month_unique
        FROM page_views
      `);

      res.json({ monthly, topPages, daily, totals: totals[0] || {} });
    } catch (err) {
      console.error("Analytics traffic error:", err);
      res.status(500).json({ error: "Failed to load traffic data" });
    }
  });

  // GET /api/admin/analytics/shop — Ashley's Shop specific traffic breakdown
  app.get("/api/admin/analytics/shop", isAuthenticated, requireBusinessOwner, async (req, res) => {
    try {
      // Total shop views (all time + this month)
      const { rows: shopTotals } = await pool.query(`
        SELECT
          COUNT(*) AS all_time_views,
          COUNT(DISTINCT visitor_id) AS all_time_unique,
          COUNT(*) FILTER (WHERE visited_at >= DATE_TRUNC('month', NOW())) AS this_month_views,
          COUNT(DISTINCT visitor_id) FILTER (WHERE visited_at >= DATE_TRUNC('month', NOW())) AS this_month_unique
        FROM page_views
        WHERE page LIKE '/nature-made-jewls%'
      `);

      // Top referrer domains for shop traffic
      const { rows: referrers } = await pool.query(`
        SELECT
          CASE
            WHEN referrer IS NULL OR referrer = '' THEN 'Direct / Unknown'
            WHEN referrer LIKE '%instagram%' THEN 'Instagram'
            WHEN referrer LIKE '%facebook%' OR referrer LIKE '%fb.com%' THEN 'Facebook'
            WHEN referrer LIKE '%google%' THEN 'Google'
            WHEN referrer LIKE '%tiktok%' THEN 'TikTok'
            WHEN referrer LIKE '%twitter%' OR referrer LIKE '%t.co%' OR referrer LIKE '%x.com%' THEN 'Twitter / X'
            WHEN referrer LIKE '%pinterest%' THEN 'Pinterest'
            WHEN referrer LIKE '%snapchat%' THEN 'Snapchat'
            WHEN referrer LIKE '%youtube%' THEN 'YouTube'
            WHEN referrer LIKE '%bing%' THEN 'Bing'
            ELSE REGEXP_REPLACE(REGEXP_REPLACE(referrer, '^https?://(www\.)?', ''), '/.*$', '')
          END AS source,
          COUNT(*) AS visits,
          COUNT(DISTINCT visitor_id) AS unique_visitors
        FROM page_views
        WHERE page LIKE '/nature-made-jewls%'
          AND visited_at >= NOW() - INTERVAL '3 months'
        GROUP BY source
        ORDER BY visits DESC
        LIMIT 12
      `);

      // Top product pages joined with jewelry_items for names
      const { rows: topProducts } = await pool.query(`
        SELECT
          pv.page,
          COUNT(*) AS views,
          COUNT(DISTINCT pv.visitor_id) AS unique_visitors,
          ji.title AS product_name
        FROM page_views pv
        LEFT JOIN jewelry_items ji ON ji.id = SUBSTRING(pv.page FROM '/nature-made-jewls/(.+)$')
        WHERE pv.page LIKE '/nature-made-jewls/%'
          AND visited_at >= DATE_TRUNC('month', NOW())
        GROUP BY pv.page, ji.title
        ORDER BY views DESC
        LIMIT 10
      `);

      // Daily trend for shop pages this month
      const { rows: daily } = await pool.query(`
        SELECT
          TO_CHAR(visited_at, 'YYYY-MM-DD') AS day,
          COUNT(*) AS views,
          COUNT(DISTINCT visitor_id) AS unique_visitors
        FROM page_views
        WHERE page LIKE '/nature-made-jewls%'
          AND visited_at >= DATE_TRUNC('month', NOW())
        GROUP BY TO_CHAR(visited_at, 'YYYY-MM-DD')
        ORDER BY day ASC
      `);

      // Monthly history for shop
      const { rows: monthly } = await pool.query(`
        SELECT
          TO_CHAR(visited_at, 'YYYY-MM') AS month,
          COUNT(*) AS total_views,
          COUNT(DISTINCT visitor_id) AS unique_visitors
        FROM page_views
        WHERE page LIKE '/nature-made-jewls%'
          AND visited_at >= NOW() - INTERVAL '12 months'
        GROUP BY TO_CHAR(visited_at, 'YYYY-MM')
        ORDER BY month DESC
        LIMIT 12
      `);

      res.json({ totals: shopTotals[0] || {}, referrers, topProducts, daily, monthly });
    } catch (err) {
      console.error("Shop analytics error:", err);
      res.status(500).json({ error: "Failed to load shop analytics" });
    }
  });

  // ── Unified dashboard endpoint ──────────────────────────────────────────────
  // Returns jobs summary, token totals, and liability metrics in one call
  app.get("/api/dashboard", isAuthenticated, requireBusinessOwner, async (req, res) => {
    try {
      const [allLeads, allUsers, liabilityData] = await Promise.all([
        storage.getLeads(),
        storage.getAllUsers(),
        getTreasuryAnalytics(),
      ]);

      const jobsByStage: Record<string, number> = {};
      for (const lead of allLeads) {
        const stage = lead.status || "unknown";
        jobsByStage[stage] = (jobsByStage[stage] || 0) + 1;
      }

      const [totalEarnedRow] = await db
        .select({ total: sql<number>`coalesce(sum(cast(${rewards.tokenAmount} as decimal)), 0)` })
        .from(rewards)
        .where(sql`cast(${rewards.tokenAmount} as decimal) > 0`);
      const totalTokensEarned = Number(totalEarnedRow?.total ?? 0);

      const [totalWalletRow] = await db
        .select({ total: sql<number>`coalesce(sum(cast(token_balance as decimal)), 0)` })
        .from(walletAccounts);
      const totalTokensInWallets = Number(totalWalletRow?.total ?? 0);

      res.json({
        jobs: {
          total: allLeads.length,
          byStage: jobsByStage,
          completed: jobsByStage["completed"] || 0,
          active: (jobsByStage["available"] || 0) + (jobsByStage["new"] || 0),
        },
        tokens: {
          totalEarned: totalTokensEarned,
          totalInWallets: totalTokensInWallets,
        },
        users: {
          total: allUsers.length,
        },
        liability: liabilityData.liability,
      });
    } catch (error) {
      console.error("Error getting dashboard:", error);
      res.status(500).json({ error: "Failed to get dashboard" });
    }
  });

