  app.get("/api/admin/marketing-network/stats", isAuthenticated, requireBusinessOwner, async (req: any, res) => {
    try {
      const referralCommissionRate = 0.05;
      const repId = String(req.query.repId || "");
      const serviceType = String(req.query.serviceType || "");
      const status = String(req.query.status || "");
      const from = String(req.query.from || "");
      const to = String(req.query.to || "");

      const repWhere = repId ? [eq(marketingReps.id, repId)] : [];
      const reps = repWhere.length
        ? await db.select().from(marketingReps).where(and(...repWhere)).orderBy(marketingReps.sortOrder)
        : await db.select().from(marketingReps).orderBy(marketingReps.sortOrder, marketingReps.displayName);

      const rows = [];
      for (const rep of reps) {
        const callParams: unknown[] = [rep.promoCode];
        let callWhere = "UPPER(promo_code) = UPPER($1)";
        if (from) { callParams.push(from); callWhere += ` AND created_at >= $${callParams.length}`; }
        if (to) { callParams.push(to); callWhere += ` AND created_at <= $${callParams.length}`; }
        const callsResult = await pool.query(`SELECT COUNT(*)::int AS calls FROM marketing_call_events WHERE ${callWhere}`, callParams);

        const leadParams: unknown[] = [rep.promoCode];
        let leadWhere = "UPPER(promo_code) = UPPER($1)";
        if (serviceType) { leadParams.push(serviceType); leadWhere += ` AND service_type = $${leadParams.length}`; }
        let leadStatusCondition = "status IN ('booked','confirmed','assigned','available','in_progress','completed')";
        if (status) {
          leadParams.push(status);
          leadWhere += ` AND status = $${leadParams.length}`;
          leadStatusCondition = `status = $${leadParams.length}`;
        }
        if (from) { leadParams.push(from); leadWhere += ` AND created_at >= $${leadParams.length}`; }
        if (to) { leadParams.push(to); leadWhere += ` AND created_at <= $${leadParams.length}`; }
        const leadStats = await pool.query(`
          SELECT
            COUNT(*)::int AS estimates,
            COUNT(*) FILTER (WHERE ${leadStatusCondition})::int AS booked,
            COALESCE(SUM(CASE WHEN ${leadStatusCondition} THEN COALESCE(total_price::numeric, base_price::numeric, 0) ELSE 0 END), 0)::float AS revenue
          FROM leads
          WHERE ${leadWhere}
        `, leadParams);

        const bookingParams: unknown[] = [rep.promoCode];
        let bookingWhere = "UPPER(qa.promo_code) = UPPER($1)";
        let bookingBookedCondition = "status IN ('booked','in_progress','completed')";
        if (status) {
          bookingParams.push(status);
          const statusParam = bookingParams.length;
          bookingWhere += ` AND b.status = $${statusParam}`;
          bookingBookedCondition = `status = $${statusParam}`;
        }
        if (serviceType) {
          bookingParams.push(serviceType);
          bookingWhere += ` AND EXISTS (
            SELECT 1
            FROM booking_service_items bsi
            WHERE bsi.booking_id = b.id AND bsi.service_code = $${bookingParams.length}
          )`;
        }
        if (from) { bookingParams.push(from); bookingWhere += ` AND b.created_at >= $${bookingParams.length}`; }
        if (to) { bookingParams.push(to); bookingWhere += ` AND b.created_at <= $${bookingParams.length}`; }
        const bookingStats = await pool.query(`
          WITH attributed_bookings AS (
            SELECT DISTINCT b.id, b.status, b.final_total
            FROM bookings b
            INNER JOIN quote_attributions qa ON qa.booking_id = b.id
            WHERE ${bookingWhere}
          )
          SELECT
            COUNT(*)::int AS estimates,
            COUNT(*) FILTER (WHERE ${bookingBookedCondition})::int AS booked,
            COALESCE(SUM(CASE WHEN ${bookingBookedCondition} THEN final_total::numeric ELSE 0 END), 0)::float AS revenue
          FROM attributed_bookings
        `, bookingParams);

        const calls = Number(callsResult.rows[0]?.calls || 0);
        const estimates = Number(leadStats.rows[0]?.estimates || 0) + Number(bookingStats.rows[0]?.estimates || 0);
        const booked = Number(leadStats.rows[0]?.booked || 0) + Number(bookingStats.rows[0]?.booked || 0);
        const revenue = Number(leadStats.rows[0]?.revenue || 0) + Number(bookingStats.rows[0]?.revenue || 0);
        const estimatedCommission = revenue * referralCommissionRate;

        rows.push({
          rep,
          calls,
          estimates,
          booked,
          revenue,
          commissionPaid: estimatedCommission,
          roi: estimatedCommission > 0 ? revenue / estimatedCommission : 0,
          split: {
            referralSource: estimatedCommission,
            crewLaborLow: revenue * 0.35,
            crewLaborHigh: revenue * 0.45,
            truckFuel: revenue * 0.10,
            marketingFund: revenue * 0.05,
            companyProfitLow: revenue * 0.35,
            companyProfitHigh: revenue * 0.45,
          },
        });
      }
      res.json({ reps: rows });
    } catch (error: any) {
      console.error("Error fetching marketing network stats:", error);
      res.status(500).json({ error: error.message || "Failed to fetch marketing network stats" });
    }
  });

  // ============ PROMO CODE ENDPOINTS ============

  // Validate a promo code (public - no auth required, just checks if valid)
  app.post("/api/promo-codes/validate", async (req: any, res) => {
    try {
      const { code, context, serviceAddress, requestedDate } = z.object({
        code: z.string().min(1).max(50),
        context: z.enum(['service', 'jewelry', 'any']).default('any'),
        serviceAddress: z.string().trim().max(500).optional(),
        requestedDate: z.string().trim().max(40).optional(),
      }).parse(req.body);
      const normalizedCode = code.toUpperCase().trim();

      if (normalizedCode === ROUTE_DAY_DISCOUNT_CODE || normalizedCode === IRONWOOD_DAILY_DISCOUNT_CODE) {
        const eligibility = getRouteDayDiscountEligibility({ serviceAddress, requestedDate });
        if (!eligibility.eligible || eligibility.code !== normalizedCode) {
          return res.status(400).json({
            valid: false,
            error: eligibility.reason,
            serviceAddressDiscountHint: eligibility,
          });
        }
      }

      const { promoCodes } = await import("@shared/schema");
      const [promo] = await db
        .select()
        .from(promoCodes)
        .where(eq(promoCodes.code, normalizedCode))
        .limit(1);

      if (!promo) return res.status(404).json({ valid: false, error: "Promo code not found" });
      if (!promo.isActive) return res.status(400).json({ valid: false, error: "This promo code is no longer active" });
      if (promo.expiresAt && new Date(promo.expiresAt) < new Date()) {
        return res.status(400).json({ valid: false, error: "This promo code has expired" });
      }
      if (promo.maxUses !== null && promo.usesCount >= promo.maxUses) {
        return res.status(400).json({ valid: false, error: "This promo code has reached its usage limit" });
      }

      const discountPercent = context === 'jewelry'
        ? parseFloat(promo.discountPercentJewelry || "0")
        : parseFloat(promo.discountPercent || "0");

      return res.json({
        valid: true,
        code: promo.code,
        description: promo.description,
        discountPercent,
        discountPercentService: parseFloat(promo.discountPercent || "0"),
        discountPercentJewelry: parseFloat(promo.discountPercentJewelry || "0"),
        rewardTokens: parseFloat(promo.rewardTokens || "0"),
        jobOffer: promo.jobOffer || null,
      });
    } catch (error: any) {
      res.status(400).json({ valid: false, error: error.message });
    }
  });

  // Apply a promo code (authenticated — credits tokens to user and referral user)
  app.post("/api/promo-codes/apply", isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.session as any).userId;
      const { code, context, enrollRewards } = z.object({
        code: z.string().min(1).max(50),
        context: z.enum(['service', 'jewelry', 'any']).default('any'),
        enrollRewards: z.boolean().optional(),
      }).parse(req.body);

      const { promoCodes, users } = await import("@shared/schema");
      const [promo] = await db
        .select()
        .from(promoCodes)
        .where(eq(promoCodes.code, code.toUpperCase().trim()))
        .limit(1);

      if (!promo) return res.status(404).json({ success: false, error: "Promo code not found" });
      if (!promo.isActive) return res.status(400).json({ success: false, error: "This promo code is no longer active" });
      if (promo.expiresAt && new Date(promo.expiresAt) < new Date()) {
        return res.status(400).json({ success: false, error: "This promo code has expired" });
      }
      if (promo.maxUses !== null && promo.usesCount >= promo.maxUses) {
        return res.status(400).json({ success: false, error: "This promo code has reached its usage limit" });
      }

      // Check that the user has a real, completed account (TOS accepted)
      const [user] = await db.select().from(users).where(eq(users.id, userId)).limit(1);
      if (!user) return res.status(404).json({ success: false, error: "User not found" });
      
      // If customer reward exists, handle enrollment
      const customerRewardRaw = parseFloat(promo.rewardTokens || "0");
      let customerReward = customerRewardRaw;

      if (customerRewardRaw > 0) {
        // If they didn't check the box and aren't already enrolled, they don't get the tokens
        // but the discount still applies.
        if (!enrollRewards && !user.rewardsEnrolled) {
          customerReward = 0;
        } else {
          // They want to enroll or are already enrolled
          if (!user.tosAccepted) {
            return res.status(403).json({
              success: false,
              error: "You must complete account setup and accept the Terms of Service before redeeming token rewards.",
            });
          }
          // Auto-enroll ONLY if they checked the box and aren't already
          if (enrollRewards && !user.rewardsEnrolled) {
            await db.update(users).set({ rewardsEnrolled: true }).where(eq(users.id, userId));
          }
        }
      }

      // Prevent the same user from using the same promo code twice
      const { rewards: rewardsSchema } = await import("@shared/schema");
      const [existingUse] = await db
        .select()
        .from(rewardsSchema)
        .where(
          and(
            eq(rewardsSchema.userId, userId),
            eq(rewardsSchema.rewardType, 'promo_code'),
            sql`${rewardsSchema.metadata}->>'promoCode' = ${promo.code}`
          )
        )
        .limit(1);

      if (existingUse) {
        return res.status(400).json({
          success: false,
          error: "You have already used this promo code.",
        });
      }

      // Increment uses count and auto-delete when fully exhausted
      const newUsesCount = promo.usesCount + 1;
      if (promo.maxUses !== null && newUsesCount >= promo.maxUses) {
        await db.delete(promoCodes).where(eq(promoCodes.id, promo.id));
      } else {
        await db.update(promoCodes)
          .set({ usesCount: newUsesCount, updatedAt: new Date() })
          .where(eq(promoCodes.id, promo.id));
      }

      // Credit reward tokens to the customer
      if (customerReward > 0) {
        await storage.creditWalletTokens(userId, customerReward);
        const { rewards: rewardsTable } = await import("@shared/schema");
        await db.insert(rewardsTable).values({
          userId,
          rewardType: 'promo_code',
          tokenAmount: customerReward.toString(),
          cashValue: "0.00",
          status: 'confirmed',
          metadata: { promoCode: promo.code, context }
        });
      }

      // Credit referral tokens to the code owner
      const referralReward = parseFloat(promo.referralRewardTokens || "0");
      if (referralReward > 0 && promo.referralUserId && promo.referralUserId !== userId) {
        await storage.creditWalletTokens(promo.referralUserId, referralReward);
        const { rewards } = await import("@shared/schema");
        await db.insert(rewards).values({
          userId: promo.referralUserId,
          rewardType: 'referral_promo',
          tokenAmount: referralReward.toString(),
          cashValue: "0.00",
          status: 'confirmed',
          metadata: { promoCode: promo.code, usedByUserId: userId, context }
        });
      }

      const discountPercent = context === 'jewelry'
        ? parseFloat(promo.discountPercentJewelry || "0")
        : parseFloat(promo.discountPercent || "0");

      return res.json({
        success: true,
        code: promo.code,
        description: promo.description,
        discountPercent,
        discountPercentService: parseFloat(promo.discountPercent || "0"),
        discountPercentJewelry: parseFloat(promo.discountPercentJewelry || "0"),
        rewardTokens: customerReward,
        referralReward,
        message: `Promo code applied! ${customerReward > 0 ? `You earned ${customerReward} JCMOVES tokens. ` : ""}${discountPercent > 0 ? `${discountPercent}% discount applied.` : ""}`,
      });
    } catch (error: any) {
      console.error("Error applying promo code:", error);
      res.status(400).json({ success: false, error: error.message });
    }
  });

  // Auto-generate a 5% jewelry booking reward coupon for the current user
  // Idempotent: returns existing unused code if one already exists for this user
  app.post("/api/promo-codes/booking-jewelry-reward", isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.session as any).userId;
      const { promoCodes } = await import("@shared/schema");

      // Check for an existing active, unused booking reward for this user
      const existing = await db
        .select()
        .from(promoCodes)
        .where(
          and(
            eq(promoCodes.referralUserId, userId),
            eq(promoCodes.isActive, true),
            sql`${promoCodes.code} LIKE 'JEWLS5-%'`,
            sql`(${promoCodes.maxUses} IS NULL OR ${promoCodes.usesCount} < ${promoCodes.maxUses})`
          )
        )
        .limit(1);

      if (existing.length > 0) {
        return res.json({ code: existing[0].code, discountPercentJewelry: 5, alreadyExisted: true });
      }

      // Generate a unique code: JEWLS5-XXXXXX
      const suffix = Math.random().toString(36).toUpperCase().slice(2, 8);
      const code = `JEWLS5-${suffix}`;

      const expiresAt = new Date();
      expiresAt.setFullYear(expiresAt.getFullYear() + 1);

      await db.insert(promoCodes).values({
        code,
        description: "5% off Nature Made Jewls — Thank you for booking with JC ON THE MOVE!",
        discountPercent: "0.00",
        discountPercentJewelry: "5.00",
        rewardTokens: "0.00",
        referralRewardTokens: "0.00",
        referralUserId: userId,
        maxUses: 1,
        isActive: true,
        expiresAt,
      });

      return res.json({ code, discountPercentJewelry: 5, alreadyExisted: false });
    } catch (error: any) {
      console.error("Error generating booking jewelry reward:", error);
      res.status(500).json({ error: error.message || "Failed to generate coupon" });
    }
  });

  // Admin: list all promo codes
  app.get("/api/admin/jcmoves-audit", isAuthenticated, requireBusinessOwner, async (req, res) => {
    try {
      const months = Math.max(1, Math.min(24, Number(req.query.months) || 6));
      const [summaryResult, payoutResult, monthlyResult] = await Promise.all([
        pool.query<{ users: number; transactions: number; total_jcmoves: string }>(
          `SELECT COUNT(DISTINCT user_id)::int AS users,
                  COUNT(*)::int AS transactions,
                  COALESCE(SUM(token_amount::numeric), 0)::text AS total_jcmoves
             FROM rewards
            WHERE status = 'confirmed'
              AND earned_date >= NOW() - ($1::int * INTERVAL '1 month')`,
          [months],
        ),
        pool.query<{ users: number; transactions: number; total_jcmoves: string; pending_customer_claims: number }>(
          `SELECT COUNT(DISTINCT recipient_user_id) FILTER (WHERE recipient_user_id IS NOT NULL)::int AS users,
                  COUNT(*)::int AS transactions,
                  COALESCE(SUM(token_amount), 0)::text AS total_jcmoves,
                  COUNT(*) FILTER (WHERE recipient_user_id IS NULL)::int AS pending_customer_claims
             FROM job_jcmoves_ledger
            WHERE created_at >= NOW() - ($1::int * INTERVAL '1 month')`,
          [months],
        ),
        pool.query<{ month: string; users: number; transactions: number; total_jcmoves: string }>(
          `SELECT to_char(date_trunc('month', earned_date), 'YYYY-MM') AS month,
                  COUNT(DISTINCT user_id)::int AS users,
                  COUNT(*)::int AS transactions,
                  COALESCE(SUM(token_amount::numeric), 0)::text AS total_jcmoves
             FROM rewards
            WHERE status = 'confirmed'
              AND earned_date >= NOW() - ($1::int * INTERVAL '1 month')
            GROUP BY 1
            ORDER BY 1`,
          [months],
        ),
      ]);
      res.json({
        months,
        generatedAt: new Date().toISOString(),
        allJcMoves: summaryResult.rows[0] || { users: 0, transactions: 0, total_jcmoves: "0" },
        paidCompletionLedger: payoutResult.rows[0] || { users: 0, transactions: 0, total_jcmoves: "0", pending_customer_claims: 0 },
        monthly: monthlyResult.rows,
      });
    } catch (error) {
      console.error("JCMOVES audit failed:", error);
      res.status(500).json({ error: "Unable to generate JCMOVES audit" });
    }
  });

