  // ── Public pricing config (used by services page) ──────────────────────────
  // ── Drive distance auto-estimate via OpenStreetMap Nominatim ──────────────
  // Calculates total one-way drive miles for a job:
  //   Moving: base→pickup + pickup→dropoff (we return pickup→dropoff + base→pickup)
  //   Load-only/Junk: base→pickup only (round trip handled by driveLineItem × 2)
  app.get("/api/utility/estimate-drive-miles", ipRateLimit({
    scope: "estimate_drive_miles_ip",
    windowMs: 5 * 60_000,
    maxHits: 60,
    message: "Too many distance lookups. Try again in a few minutes.",
  }), async (req, res) => {
    const pickupAddr = req.query.pickup as string || req.query.address as string;
    const dropoffAddr = req.query.dropoff as string;
    if (!pickupAddr || pickupAddr.trim().length < 4) {
      return res.json({ miles: 0, error: "No pickup address" });
    }
    const BASE_LAT = 46.4539; // Ironwood, MI
    const BASE_LNG = -90.1715;

    function haversine(lat1: number, lng1: number, lat2: number, lng2: number) {
      const R = 3958.8; // Earth radius in miles
      const dLat = ((lat2 - lat1) * Math.PI) / 180;
      const dLng = ((lng2 - lng1) * Math.PI) / 180;
      const a =
        Math.sin(dLat / 2) ** 2 +
        Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
      return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    }

    async function geocode(addr: string): Promise<{ lat: number; lon: number } | null> {
      try {
        const url = `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(addr)}&format=json&limit=1&countrycodes=us`;
        const r = await fetch(url, { headers: { "User-Agent": "JCOnTheMove/1.0 contact@jcontmove.com" } });
        if (!r.ok) return null;
        const data: Array<{ lat: string; lon: string }> = await r.json() as any;
        if (!data.length) return null;
        return { lat: parseFloat(data[0].lat), lon: parseFloat(data[0].lon) };
      } catch { return null; }
    }

    try {
      const estimate = await estimateDriveMilesForChatbot(pickupAddr, dropoffAddr);
      return res.json(estimate);
      /*
      const pickup = await geocode(pickupAddr);
      if (!pickup) return res.json({ miles: 0, note: "Pickup address not found" });

      // base→pickup segment (always included)
      const baseToPickup = haversine(BASE_LAT, BASE_LNG, pickup.lat, pickup.lon);
      let totalOneWay = baseToPickup;
      let route = `base→pickup(${Math.round(baseToPickup)}mi)`;

      // pickup→dropoff segment (moving jobs with a destination)
      if (dropoffAddr && dropoffAddr.trim().length >= 4) {
        const dropoff = await geocode(dropoffAddr);
        if (dropoff) {
          const pickupToDropoff = haversine(pickup.lat, pickup.lon, dropoff.lat, dropoff.lon);
          totalOneWay += pickupToDropoff;
          route += `+dropoff(${Math.round(pickupToDropoff)}mi)`;
        }
      }

      const estimated = Math.ceil(totalOneWay * 1.25); // road-factor multiplier
      return res.json({ miles: estimated, straight: Math.round(totalOneWay), route });
      */
    } catch (err) {
      return res.json({ miles: 0, error: err instanceof Error ? err.message : String(err) });
    }
  });

  // ── Live Crew Status (customer-facing, no auth required) ───────────────────
  // Returns a readiness badge driven by real crew availability + today's job load.
  // Status keys: ready | limited | high_demand | scheduling_ahead
  app.get("/api/utility/verify-address", ipRateLimit({
    scope: "verify_address_ip",
    windowMs: 5 * 60_000,
    maxHits: 80,
    message: "Too many address checks. Try again in a few minutes.",
  }), async (req, res) => {
    const address = String(req.query.address || "").trim();
    if (address.length < 6) {
      return res.json({ verified: false, reason: "Address is too short" });
    }

    const componentValue = (
      components: Array<{ long_name: string; short_name: string; types: string[] }>,
      type: string,
      short = false,
    ) => {
      const match = components.find((component) => component.types.includes(type));
      return match ? (short ? match.short_name : match.long_name) : "";
    };

    try {
      const googleKey = process.env.GOOGLE_MAPS_API_KEY || process.env.VITE_GOOGLE_MAPS_API_KEY || process.env.GOOGLE_PLACES_API_KEY || "";
      if (googleKey) {
        const url = `https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(address)}&components=country:US&key=${googleKey}`;
        const response = await fetch(url);
        if (response.ok) {
          const data = await response.json() as {
            status: string;
            results?: Array<{
              formatted_address?: string;
              address_components?: Array<{ long_name: string; short_name: string; types: string[] }>;
            }>;
          };
          const place = data.results?.[0];
          const components = place?.address_components || [];
          const has = (type: string) => components.some((component) => component.types.includes(type));
          if (data.status === "OK" && place?.formatted_address && has("route")) {
            const city = componentValue(components, "locality") || componentValue(components, "sublocality");
            const state = componentValue(components, "administrative_area_level_1", true);
            const zip = componentValue(components, "postal_code");
            return res.json({
              verified: Boolean(city && state && zip),
              provider: "google",
              fullAddress: place.formatted_address,
              city,
              state,
              zip,
            });
          }
        }
      }

      const fallbackUrl = `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(address)}&format=json&limit=1&addressdetails=1&countrycodes=us`;
      const fallback = await fetch(fallbackUrl, {
        headers: { "User-Agent": "JCOnTheMove/1.0 contact@jconthemove.com" },
      });
      if (fallback.ok) {
        const data = await fallback.json() as Array<{
          display_name?: string;
          address?: { city?: string; town?: string; village?: string; state?: string; postcode?: string };
        }>;
        const place = data[0];
        if (place?.display_name) {
          return res.json({
            verified: true,
            provider: "openstreetmap",
            fullAddress: place.display_name,
            city: place.address?.city || place.address?.town || place.address?.village || "",
            state: place.address?.state || "",
            zip: place.address?.postcode || "",
          });
        }
      }

      return res.json({ verified: false, reason: "Address not found" });
    } catch (error) {
      return res.json({ verified: false, reason: error instanceof Error ? error.message : "Address check failed" });
    }
  });

  app.get("/api/crew-status", async (_req, res) => {
    try {
      // All approved employees/admins with their duty-window fields
      const allCrew = await db.select({
        id:             users.id,
        isAvailable:    users.isAvailable,
        availableUntil: users.availableUntil,
      }).from(users).where(
        and(
          eq(users.status, "approved"),
          or(
            eq(users.role, "employee"),
            and(
              inArray(users.role, ["admin", "business_owner"]),
              sql`COALESCE(${users.capabilities}, ARRAY[]::text[]) @> ARRAY['mover']::text[]`,
            ),
          ),
        )
      );

      // "On duty" = isAvailable=true AND availableUntil is either unset or still in the future.
      // The background interval auto-clears expired windows, but we double-check here in case
      // the interval hasn't fired yet — avoids counting workers whose shift just ended.
      const now = new Date();
      const availableCrew = allCrew.filter(c =>
        c.isAvailable && (!c.availableUntil || new Date(c.availableUntil) > now)
      );

      // Today's date in Central Time (Ironwood, MI) — YYYY-MM-DD
      const today = new Date().toLocaleDateString("en-CA", { timeZone: "America/Chicago" });
      const ctHour = parseInt(
        new Date().toLocaleTimeString("en-US", { timeZone: "America/Chicago", hour: "numeric", hour12: false }),
        10
      );

      // Active leads (non-completed) — fetch and filter in JS to avoid text date format issues
      const activeLeads = await db.select({
        status:   leads.status,
        moveDate: leads.moveDate,
        confirmedDate: leads.confirmedDate,
        crewSize: leads.crewSize,
      }).from(leads).where(
        or(eq(leads.status, "available"), eq(leads.status, "quote_requested"))
      );

      const todayLeads  = activeLeads.filter(l => l.moveDate === today || l.confirmedDate === today);
      const liveJobs    = todayLeads.filter(l => l.status === "available");

      const crewCapacity = availableCrew.length;
      // Count crew slots consumed by active (in-progress) jobs
      const activeLoad   = liveJobs.reduce((s, j) => s + (j.crewSize || 2), 0);

      // ── New 3-state color logic ──────────────────────────────────────────────
      // Green  : no confirmed/assigned jobs today (quote_requested rows don't count)
      // Yellow : confirmed jobs exist today but activeLoad ≤ 50% of on-duty crew
      // Red    : more than half the on-duty crew is currently on assignment
      // Gray   : after 6 PM CT or no crew online at all
      // Note: liveJobs = status "available" = actual booked/assigned jobs only.
      //       quote_requested leads do NOT push the beacon to yellow.
      type StatusKey = "available" | "jobs_today" | "busy" | "scheduling_ahead";
      let status: StatusKey = "scheduling_ahead";

      if (ctHour >= 18 || crewCapacity === 0) {
        status = "scheduling_ahead";
      } else if (liveJobs.length === 0) {
        // No confirmed jobs today (quotes alone don't count) → fully open
        status = "available";
      } else if (activeLoad <= crewCapacity / 2) {
        // Confirmed jobs exist but ≤50% of crew assigned → some capacity remains
        status = "jobs_today";
      } else {
        // More than half the crew is on confirmed assignment
        status = "busy";
      }

      const PAYLOADS: Record<StatusKey, object> = {
        available: {
          status: "available",
          title: "Available Now",
          subtitle: "No jobs booked yet — first come, first served",
          badge: "Open",
          tone: "green",
          ctaHint: "Book now — slots fill fast once the day starts",
        },
        jobs_today: {
          status: "jobs_today",
          title: "Jobs Booked Today",
          subtitle: "Crew is active — some same-day spots remain",
          badge: "Limited",
          tone: "yellow",
          ctaHint: "Grab a slot before the crew fills up",
        },
        busy: {
          status: "busy",
          title: "Crew Busy",
          subtitle: "More than half our crew is on assignment",
          badge: "Busy",
          tone: "red",
          ctaHint: "Schedule ahead — we'll lock in your time",
        },
        scheduling_ahead: {
          status: "scheduling_ahead",
          title: "Scheduling Ahead",
          subtitle: "Request your preferred time — we follow up fast",
          badge: "Scheduling",
          tone: "gray",
          ctaHint: "Quotes are still open — book any time",
        },
      };

      return res.json({ ...PAYLOADS[status], refreshedAt: new Date().toISOString() });
    } catch (err) {
      console.error("[crew-status] error:", err);
      return res.json({
        status: "jobs_today",
        title: "Jobs Booked Today",
        subtitle: "Crew is active — some same-day spots remain",
        badge: "Limited",
        tone: "yellow",
        ctaHint: "Grab a slot before the crew fills up",
        refreshedAt: new Date().toISOString(),
      });
    }
  });

